const POLL: Duration = Duration::from_millis(500);

/// Narrowest a grid tile gets before the grid drops a column.
const TILE: f32 = 100.;
/// Items area wide enough for the list's format and bin columns.
const WIDE_LIST: f32 = 420.;

actions!(
    media_pool,
    [
        RemoveSelected,
        PlaySelected,
        OpenSelected,
        FocusSearch,
        SelectAll,
        SelectPrev,
        SelectNext,
        SelectUp,
        SelectDown,
        Deselect,
        InsertSelected,
        OverwriteSelected,
        MarkSourceIn,
        MarkSourceOut,
        RenameSelected,
        OpenParentBin,
    ]
);

fn bind_keys(cx: &mut App) {
    static BOUND: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
    if BOUND.swap(true, std::sync::atomic::Ordering::SeqCst) {
        return;
    }
    // Not while typing in the search or name fields.
    let items = Some("MediaPool && !Input");
    cx.bind_keys([
        KeyBinding::new("delete", RemoveSelected, items),
        KeyBinding::new("backspace", RemoveSelected, items),
        KeyBinding::new("space", PlaySelected, items),
        KeyBinding::new("enter", OpenSelected, items),
        KeyBinding::new("/", FocusSearch, items),
        KeyBinding::new("cmd-a", SelectAll, items),
        KeyBinding::new("ctrl-a", SelectAll, items),
        KeyBinding::new("left", SelectPrev, items),
        KeyBinding::new("right", SelectNext, items),
        KeyBinding::new("up", SelectUp, items),
        KeyBinding::new("down", SelectDown, items),
        KeyBinding::new("escape", Deselect, items),
        KeyBinding::new(",", InsertSelected, items),
        KeyBinding::new("f2", RenameSelected, items),
        KeyBinding::new("cmd-up", OpenParentBin, items),
        KeyBinding::new("ctrl-up", OpenParentBin, items),
        KeyBinding::new("i", MarkSourceIn, items),
        KeyBinding::new("o", MarkSourceOut, items),
        KeyBinding::new(".", OverwriteSelected, items),
    ]);
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Layout {
    Grid,
    List,
}

pub struct MediaPoolPanel {
    state: Entity<EditorState>,
    focus: FocusHandle,
    search: Entity<InputState>,
    bin_input: Entity<InputState>,
    /// The item being renamed and its name field.
    renaming_item: Option<MediaId>,
    item_input: Entity<InputState>,
    layout: Layout,
    /// The bin open in the pool; `None` is the top level.
    bin: Option<BinId>,
    renaming: Option<BinId>,
    selected: Option<MediaId>,
    /// Items selected with it, by cmd/ctrl- or shift-click or the band.
    also: Vec<MediaId>,
    /// Selected folders.
    chosen: Vec<BinId>,
    /// What was clicked or stepped to last: where shift-click runs from
    /// and the arrow keys move from.
    cursor: Option<Entry>,
    thumbs: Thumbs,
    jobs: Vec<JobStatus>,
    /// Proxy creation progress, written from background threads.
    proxies: Arc<Mutex<HashMap<MediaId, f32>>>,
    /// Proxies already looked for, by path (see `hdr.rs`).
    hdr_proxies: std::collections::HashSet<std::path::PathBuf>,
    /// Files dragged in from outside, while they are over the items.
    dropping: Option<Vec<PathBuf>>,
    /// The items area last frame, for the grid's columns and for keeping
    /// the selection in view.
    area: Rc<Cell<Bounds<Pixels>>>,
    /// The grid's columns last frame, for moving up and down.
    cols: Cell<u16>,
    scroll: ScrollHandle,
    /// Scroll the selected item into view when it next paints.
    reveal: Rc<Cell<bool>>,
    /// The selection in pool order, when it is more than one item: what
    /// grabbing one of them drags.
    dragged: Vec<MediaId>,
    /// The video tile the pointer skims, and where across it, 0..1.
    skim: Option<(MediaId, f32)>,
    /// Where each item (`Some`) and folder (`None`) painted last frame,
    /// for the rubber band.
    placed: Rc<RefCell<Vec<Placed>>>,
    /// A rubber band being dragged across empty space.
    band: Option<Band>,
    _subscriptions: Vec<Subscription>,
    _poll: Task<()>,
}

impl MediaPoolPanel {
    pub fn new(state: Entity<EditorState>, window: &mut Window, cx: &mut Context<Self>) -> Self {
        bind_keys(cx);
        let search = cx.new(|cx| InputState::new(window, cx).placeholder("Search media"));
        let bin_input = cx.new(|cx| InputState::new(window, cx));
        let item_input = cx.new(|cx| InputState::new(window, cx));
        let _subscriptions = vec![
            cx.observe(&state, |_, _, cx| cx.notify()),
            cx.subscribe(&search, |_, _, _: &InputEvent, cx| cx.notify()),
            cx.subscribe_in(&item_input, window, |this, input, ev, window, cx| {
                if matches!(ev, InputEvent::PressEnter { .. } | InputEvent::Blur) {
                    let name = input.read(cx).value().trim().to_owned();
                    this.finish_item_rename(name, window, cx);
                }
            }),
            cx.subscribe_in(&bin_input, window, |this, input, ev, _, cx| {
                if matches!(ev, InputEvent::PressEnter { .. } | InputEvent::Blur) {
                    let name = input.read(cx).value().trim().to_owned();
                    this.finish_rename(name, cx);
                }
            }),
        ];
        let _poll = cx.spawn(async move |this, cx| {
            loop {
                cx.background_executor().timer(POLL).await;
                if this.update(cx, |this, cx| this.poll(cx)).is_err() {
                    break;
                }
            }
        });
        let selected = crate::demo::enabled()
            .then(|| state.read(cx).bus.project().media.first().map(|m| m.id))
            .flatten();
        if let Some(form) = crate::demo::generate_form() {
            cx.defer_in(window, move |this: &mut Self, window, cx| {
                match form.as_str() {
                    "voiceover" => this.open_voiceover(None, window, cx),
                    "voices" | "voices-describe" | "voices-audio" => {
                        let start = match form.as_str() {
                            "voices-describe" => crate::ui::voices::Start::Describe {
                                description: String::new(),
                            },
                            "voices-audio" => crate::ui::voices::Start::Clone {
                                files: Vec::new(),
                                name: String::new(),
                            },
                            _ => crate::ui::voices::Start::Find,
                        };
                        crate::ui::voices::open(this.state.clone(), start, None, window, cx)
                    }
                    "sfx" => this.open_generate(generate::Kind::SoundEffect, window, cx),
                    "video" => {
                        // Without a provider set, the first model fal offers.
                        let model = this.video_model(cx).or_else(|| {
                            let fal = flikk_cloud::provider("fal")?;
                            let first =
                                fal.offer(flikk_core::cloud::Capability::Video)?.models[0].id;
                            fal.api.video_model(first).cloned()
                        });
                        if let Some(model) = model {
                            this.open_video(model, window, cx);
                        }
                    }
                    _ => this.open_generate(generate::Kind::Music, window, cx),
                }
            });
        }
        Self {
            state,
            focus: cx.focus_handle(),
            search,
            bin_input,
            renaming_item: None,
            item_input,
            layout: Layout::Grid,
            bin: None,
            renaming: None,
            selected,
            also: Vec::new(),
            chosen: Vec::new(),
            cursor: None,
            thumbs: Thumbs::default(),
            jobs: Vec::new(),
            proxies: Arc::default(),
            hdr_proxies: Default::default(),
            dropping: None,
            area: Rc::default(),
            cols: Cell::new(1),
            scroll: ScrollHandle::default(),
            reveal: Rc::default(),
            dragged: Vec::new(),
            skim: None,
            placed: Rc::default(),
            band: None,
            _subscriptions,
            _poll,
        }
    }

    fn poll(&mut self, cx: &mut Context<Self>) {
        let jobs = self
            .state
            .read(cx)
            .services
            .analysis
            .as_ref()
            .map(|a| a.jobs())
            .unwrap_or_default();
        self.refresh_proxies(cx);
        let proxying = !self.proxies.lock().unwrap().is_empty();
        if jobs != self.jobs || proxying {
            self.jobs = jobs;
            cx.notify();
        }
    }

    /// The item's background work, `None` when idle.
    fn progress(&self, id: MediaId) -> Option<Progress> {
        if let Some(f) = self.proxies.lock().unwrap().get(&id) {
            return Some(Progress::Proxy(*f));
        }
        let job = self.jobs.iter().rev().find(|j| j.media == Some(id))?;
        match &job.state {
            JobState::Queued => Some(Progress::Queued),
            JobState::Running { fraction } => Some(Progress::Analyzing(*fraction)),
            JobState::Done => None,
            JobState::Failed { .. } => Some(Progress::Failed),
        }
    }

    /// The item's "Analyze" entry; `None` for images, which are not
    /// analyzed.
    fn analyze_entry(&self, id: MediaId, cx: &App) -> Option<AnalyzeEntry> {
        let state = self.state.read(cx);
        let item = state.bus.project().media(id)?;
        let analysis = state.services.analysis.as_ref()?;
        if item.kind == MediaKind::Image {
            return None;
        }
        let job = self.jobs.iter().rev().find(|j| j.media == Some(id));
        let fp = item.fingerprint.as_ref();
        let script = item.generated.as_deref().and_then(|g| g.script());
        let again = fp.and_then(|fp| analysis.analysis(fp)).is_some();
        Some(match job.map(|j| &j.state) {
            Some(JobState::Queued) => AnalyzeEntry::Queued,
            Some(JobState::Running { .. }) => AnalyzeEntry::Running,
            // A file that could not be read has nothing to analyze.
            _ if fp.is_none() => AnalyzeEntry::Unreadable,
            // A voiceover's script stands in for transcription.
            _ if script.is_none() && !state.models_ready() => AnalyzeEntry::SetUp,
            _ => AnalyzeEntry::Ready { again },
        })
    }

    // ------------------------------------------------------------ actions

    fn analyze(&mut self, id: MediaId, again: bool, cx: &mut Context<Self>) {
        self.state.update(cx, |s, cx| s.analyze(id, again, cx));
        self.poll(cx);
    }

    fn prompt_import(&mut self, cx: &mut Context<Self>) {
        let paths = cx.prompt_for_paths(PathPromptOptions {
            files: true,
            directories: true,
            multiple: true,
            prompt: None,
        });
        cx.spawn(async move |this, cx| {
            if let Ok(Ok(Some(paths))) = paths.await {
                this.update(cx, |this, cx| this.import(paths, this.bin, cx))
                    .ok();
            }
        })
        .detach();
    }

    /// A click on item `id`.
    fn select(&mut self, id: MediaId, open: bool, window: &mut Window, cx: &mut Context<Self>) {
        self.click(Entry::Media(id), open, window, cx)
    }

    /// A click on an item or folder: cmd/ctrl adds or drops it, shift
    /// takes the run from the last one clicked, and a double click opens
    /// it.
    fn click(&mut self, entry: Entry, open: bool, window: &mut Window, cx: &mut Context<Self>) {
        let naming = match entry {
            Entry::Media(id) => self.renaming_item == Some(id),
            Entry::Folder(id) => self.renaming == Some(id),
        };
        if naming {
            // A click in its name field.
            return;
        }
        window.focus(&self.focus, cx);
        let m = window.modifiers();
        if open {
            match entry {
                Entry::Folder(id) => self.open_bin(Some(id), cx),
                Entry::Media(id) => {
                    self.set_entries(&[entry]);
                    self.cursor = Some(entry);
                    self.open(id, cx);
                }
            }
            cx.notify();
            return;
        }
        if m.shift
            && let Some(anchor) = self.cursor
        {
            let order = self.order(cx);
            let at = |e: Entry| order.iter().position(|x| *x == e);
            if let Some((a, b)) = at(anchor).zip(at(entry)) {
                self.set_entries(&order[a.min(b)..=a.max(b)]);
                cx.notify();
                return;
            }
        }
        if m.secondary() {
            let mut entries = self.entries();
            match entries.iter().position(|e| *e == entry) {
                Some(i) => {
                    entries.remove(i);
                    if entry == Entry::Media(self.selected.unwrap_or_default()) {
                        // The next in the selection leads.
                        self.selected = None;
                    }
                }
                None => entries.push(entry),
            }
            self.set_entries(&entries);
            self.cursor = Some(entry);
            cx.notify();
            return;
        }
        self.set_entries(&[entry]);
        self.cursor = Some(entry);
        cx.notify();
    }

    /// Folders, then items, as the pool shows them.
    fn order(&self, cx: &App) -> Vec<Entry> {
        let folders = self
            .folders(cx)
            .into_iter()
            .map(|(b, _)| Entry::Folder(b.id));
        let items = self
            .visible_items(cx)
            .into_iter()
            .map(|m| Entry::Media(m.id));
        folders.chain(items).collect()
    }

    /// Everything selected: folders, then items with the lead first.
    fn entries(&self) -> Vec<Entry> {
        let folders = self.chosen.iter().map(|f| Entry::Folder(*f));
        let items = self.selection().into_iter().map(Entry::Media);
        folders.chain(items).collect()
    }

    /// Select `entries`; the item leading stays so if it is among them.
    fn set_entries(&mut self, entries: &[Entry]) {
        let media: Vec<MediaId> = entries
            .iter()
            .filter_map(|e| match e {
                Entry::Media(m) => Some(*m),
                Entry::Folder(_) => None,
            })
            .collect();
        self.chosen = entries
            .iter()
            .filter_map(|e| match e {
                Entry::Folder(f) => Some(*f),
                Entry::Media(_) => None,
            })
            .collect();
        let lead = self
            .selected
            .filter(|s| media.contains(s))
            .or(media.first().copied());
        self.selected = lead;
        self.also = media.into_iter().filter(|m| Some(*m) != lead).collect();
    }

    /// What an action on `entry` applies to: the selection when `entry`
    /// is in it, else `entry` alone. As items and folders.
    fn split_of(&self, entry: Entry) -> (Vec<MediaId>, Vec<BinId>) {
        let entries = self.entries();
        let entries = if entries.contains(&entry) {
            entries
        } else {
            vec![entry]
        };
        let mut media = Vec::new();
        let mut folders = Vec::new();
        for e in entries {
            match e {
                Entry::Media(m) => media.push(m),
                Entry::Folder(f) => folders.push(f),
            }
        }
        (media, folders)
    }

    /// `,` and `.`: edit the selection into the timeline at the
    /// playhead, in pool order.
    fn edit_selected(&mut self, mode: InsertMode, cx: &mut Context<Self>) {
        let Some(first) = self.selected else {
            return;
        };
        let ids = self.in_pool_order(&self.group_of(first), cx);
        self.state
            .update(cx, |s, cx| s.edit_at_playhead(&ids, mode, cx));
    }

    /// `ids` in the order the pool shows them.
    fn in_pool_order(&self, ids: &[MediaId], cx: &App) -> Vec<MediaId> {
        self.visible_items(cx)
            .iter()
            .map(|m| m.id)
            .filter(|id| ids.contains(id))
            .collect()
    }

    /// Clear the selection, which closes the details.
    fn deselect(&mut self, cx: &mut Context<Self>) {
        self.cursor = None;
        if self.selected.take().is_some() || !self.also.is_empty() || !self.chosen.is_empty() {
            self.also.clear();
            self.chosen.clear();
            cx.notify();
        }
    }

    /// Play a sound; show anything else in the viewer, at the frame the
    /// pointer skims.
    fn open(&mut self, id: MediaId, cx: &mut Context<Self>) {
        let item = self.state.read(cx).bus.project().media(id).cloned();
        let skimmed = self.skim.filter(|(m, _)| *m == id).map(|(_, f)| f);
        match item {
            Some(item) if self.state.read(cx).can_listen(&item) => {
                self.state.update(cx, |s, cx| s.toggle_source(&item, cx));
            }
            Some(item) => self.state.update(cx, |s, cx| {
                s.open_source(id, cx);
                if let Some(f) = skimmed {
                    s.seek_source(&item, f, cx);
                }
            }),
            None => {}
        }
    }

    /// Space: play or pause the selected sound or video from the pool.
    fn play_selected(&mut self, cx: &mut Context<Self>) {
        let Some(item) = self.selected_item(cx) else {
            return;
        };
        let state = self.state.read(cx);
        let playable = match item.kind {
            MediaKind::Audio => state.can_listen(&item),
            MediaKind::Video => state.services.media.is_some() && !state.offline.contains(&item.id),
            MediaKind::Image => false,
        };
        if playable {
            self.state.update(cx, |s, cx| s.toggle_source(&item, cx));
        } else if item.kind == MediaKind::Image {
            self.state.update(cx, |s, cx| s.open_source(item.id, cx));
        }
    }

    /// The selected items, the one clicked first leading.
    fn selection(&self) -> Vec<MediaId> {
        self.selected
            .into_iter()
            .chain(self.also.iter().copied())
            .collect()
    }

    /// What an action on `id` applies to: the selection when `id` is in
    /// it, else `id` alone.
    fn group_of(&self, id: MediaId) -> Vec<MediaId> {
        let selection = self.selection();
        if selection.contains(&id) {
            selection
        } else {
            vec![id]
        }
    }

    /// Arrow keys: move the selection `by` places through the folders and
    /// items that show, keeping it in view.
    fn step(&mut self, by: isize, cx: &mut Context<Self>) {
        let order = self.order(cx);
        if order.is_empty() {
            return;
        }
        let from = self.cursor.or(self.selected.map(Entry::Media));
        let at = from.and_then(|c| order.iter().position(|e| *e == c));
        let next = match at {
            Some(at) => (at as isize + by).clamp(0, order.len() as isize - 1) as usize,
            None if by < 0 => order.len() - 1,
            None => 0,
        };
        self.set_entries(&[order[next]]);
        self.cursor = Some(order[next]);
        self.reveal.set(true);
        cx.notify();
    }

    /// The rows the arrow keys move by: a grid row up or down, one item
    /// in the list.
    fn row_step(&self) -> isize {
        match self.layout {
            Layout::Grid => self.cols.get().max(1) as isize,
            Layout::List => 1,
        }
    }

    fn select_all(&mut self, cx: &mut Context<Self>) {
        let order = self.order(cx);
        self.set_entries(&order);
        cx.notify();
    }

    /// Ask, then remove `ids` from the project together with their clips.
    fn confirm_remove(&mut self, ids: Vec<MediaId>, window: &mut Window, cx: &mut Context<Self>) {
        let state = self.state.read(cx);
        let project = state.bus.project();
        let ids: Vec<MediaId> = ids
            .into_iter()
            .filter(|i| project.media(*i).is_some())
            .collect();
        let title = match ids.as_slice() {
            [] => return,
            [one] => {
                let name = project.media(*one).map(item_name).unwrap_or_default();
                format!("Remove “{name}” from the project?")
            }
            many => format!("Remove {} items from the project?", many.len()),
        };
        let clips: usize = ids.iter().map(|i| state.clips_using(*i).len()).sum();
        let (state, panel) = (self.state.clone(), cx.entity().downgrade());
        window.open_confirm(cx, move |dialog, _, _| {
            let (state, panel, many) = (state.clone(), panel.clone(), ids.len() > 1);
            let ids = ids.clone();
            let dialog =
                dialog
                    .title(title.clone())
                    .destructive()
                    .confirm("Remove", move |_, cx| {
                        state.update(cx, |s, cx| s.remove_media(&ids, cx));
                        let _ = panel.update(cx, |this, cx| {
                            this.also.retain(|a| !ids.contains(a));
                            if this.selected.is_some_and(|s| ids.contains(&s)) {
                                this.selected = None;
                                this.also.clear();
                            }
                            cx.notify();
                        });
                        true
                    });
            match (clips, many) {
                (0, _) => dialog,
                (1, false) => dialog.description("Its clip is removed from the timeline too."),
                (n, false) => {
                    dialog.description(format!("Its {n} clips are removed from the timeline too."))
                }
                (1, true) => dialog.description("Their clip is removed from the timeline too."),
                (n, true) => dialog.description(format!(
                    "Their {n} clips are removed from the timeline too."
                )),
            }
        });
    }

    fn update_media(&self, item: MediaItem, cx: &mut Context<Self>) {
        self.state.update(cx, |s, cx| {
            s.execute(Command::UpdateMedia { media: item }, cx);
        });
    }

    /// The selected items to sync when `id` is one of them, reference
    /// first, and whether they hold a recorder and a camera.
    fn sync_group(&self, id: MediaId, cx: &App) -> Option<(Vec<MediaId>, bool)> {
        let selected = self.selected?;
        if self.also.is_empty() || (selected != id && !self.also.contains(&id)) {
            return None;
        }
        let project = self.state.read(cx).bus.project();
        let mut all = vec![selected];
        all.extend(&self.also);
        let group = flikk_core::sync::pool_order(project, &all);
        if group.len() < 2 {
            return None;
        }
        let kind = |k| {
            group
                .iter()
                .any(|m| project.media(*m).is_some_and(|i| i.kind == k))
        };
        let recorder = kind(MediaKind::Audio) && kind(MediaKind::Video);
        Some((group, recorder))
    }

    fn selected_item(&self, cx: &App) -> Option<MediaItem> {
        let id = self.selected?;
        self.state.read(cx).bus.project().media(id).cloned()
    }

    /// Put `media` and `folders` in folder `to` (`None`: the top level),
    /// as one undo step. A folder doesn't go into itself or a folder in
    /// it.
    fn move_entries(
        &mut self,
        media: &[MediaId],
        folders: &[BinId],
        to: Option<BinId>,
        cx: &mut Context<Self>,
    ) {
        let project = self.state.read(cx).bus.project();
        let tree = BinTree::of(&project.bins);
        let moving: Vec<BinId> = folders
            .iter()
            .copied()
            .filter(|f| !tree.within(to, *f))
            .collect();
        let mut commands = Vec::new();
        if project
            .bins
            .iter()
            .any(|b| moving.contains(&b.id) && b.parent != to)
        {
            let bins = project
                .bins
                .iter()
                .map(|b| Bin {
                    parent: if moving.contains(&b.id) { to } else { b.parent },
                    ..b.clone()
                })
                .collect();
            commands.push(Command::SetBins { bins });
        }
        commands.extend(
            media
                .iter()
                .filter_map(|id| project.media(*id))
                .filter(|item| item.bin != to)
                .map(|item| Command::UpdateMedia {
                    media: MediaItem {
                        bin: to,
                        ..item.clone()
                    },
                }),
        );
        if !commands.is_empty() {
            self.state
                .update(cx, |s, cx| s.execute_batch(commands, "move_to_bin", cx));
        }
    }

    fn bins(&self, cx: &App) -> Vec<Bin> {
        self.state.read(cx).bus.project().bins.clone()
    }

    /// A folder in `parent`, which opens, named as it is typed.
    fn new_bin(&mut self, parent: Option<BinId>, window: &mut Window, cx: &mut Context<Self>) {
        self.open_bin(parent, cx);
        // Searching hides folders; the new one has to show to be named.
        self.search.update(cx, |s, cx| s.set_value("", window, cx));
        let mut bins = self.bins(cx);
        let n = bins.len() + 1;
        let bin = Bin {
            id: BinId::new(),
            name: format!("Folder {n}"),
            parent,
        };
        let id = bin.id;
        bins.push(bin);
        self.state.update(cx, |s, cx| {
            s.execute(Command::SetBins { bins }, cx);
        });
        self.start_rename(id, window, cx);
    }

    fn start_rename(&mut self, id: BinId, window: &mut Window, cx: &mut Context<Self>) {
        let name = self
            .bins(cx)
            .into_iter()
            .find(|b| b.id == id)
            .map(|b| b.name)
            .unwrap_or_default();
        self.renaming = Some(id);
        // Typing replaces the name; an empty entry keeps it.
        self.bin_input.update(cx, |i, cx| {
            i.set_value("", window, cx);
            i.set_placeholder(name, window, cx);
            i.focus(window, cx);
        });
        cx.notify();
    }

    /// Remove `media` and delete `folders` with everything in them; one
    /// undo step. Items alone ask as [`Self::confirm_remove`] does; empty
    /// folders go at once; otherwise this asks first, saying what goes.
    fn confirm_delete(
        &mut self,
        media: Vec<MediaId>,
        folders: Vec<BinId>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if folders.is_empty() {
            self.confirm_remove(media, window, cx);
            return;
        }
        let state = self.state.read(cx);
        let project = state.bus.project();
        let tree = BinTree::of(&project.bins);
        let gone = |bin: Option<BinId>| folders.iter().any(|f| tree.within(bin, *f));
        let inner = project
            .bins
            .iter()
            .filter(|b| !folders.contains(&b.id) && gone(Some(b.id)))
            .count();
        let held: Vec<MediaId> = project
            .media
            .iter()
            .filter(|m| gone(m.bin))
            .map(|m| m.id)
            .collect();
        let mut all = media.clone();
        all.extend(held.iter().filter(|h| !media.contains(h)));
        if all.is_empty() && inner == 0 {
            self.delete_entries(&folders, Vec::new(), cx);
            return;
        }
        let clips: usize = all.iter().map(|m| state.clips_using(*m).len()).sum();
        let plural = |n: usize, one: &str, many: &str| match n {
            1 => format!("1 {one}"),
            n => format!("{n} {many}"),
        };
        let clips_go = (clips > 0).then(|| {
            format!(
                " {} on the timeline go too.",
                plural(clips, "clip", "clips")
            )
        });
        let (title, description, confirm) = match (folders.as_slice(), media.is_empty()) {
            ([one], true) => {
                let name = project
                    .bins
                    .iter()
                    .find(|b| b.id == *one)
                    .map_or(String::new(), |b| b.name.clone());
                let held: Vec<String> =
                    [(held.len(), "item", "items"), (inner, "folder", "folders")]
                        .into_iter()
                        .filter(|(n, _, _)| *n > 0)
                        .map(|(n, one, many)| plural(n, one, many))
                        .collect();
                (
                    format!("Delete “{name}” and everything in it?"),
                    format!("It holds {}.", held.join(" and ")),
                    "Delete",
                )
            }
            _ => (
                format!(
                    "Remove {} items from the project?",
                    folders.len() + media.len()
                ),
                "Folders go with everything in them.".to_owned(),
                "Remove",
            ),
        };
        let description = description + clips_go.as_deref().unwrap_or("");
        let panel = cx.entity().downgrade();
        window.open_confirm(cx, move |dialog, _, _| {
            let (panel, folders, all) = (panel.clone(), folders.clone(), all.clone());
            dialog
                .title(title.clone())
                .description(description.clone())
                .destructive()
                .confirm(confirm, move |_, cx| {
                    let _ = panel.update(cx, |this, cx| {
                        this.delete_entries(&folders, all.clone(), cx)
                    });
                    true
                })
        });
    }

    /// Remove `folders`, the folders in them and `media`.
    fn delete_entries(&mut self, folders: &[BinId], media: Vec<MediaId>, cx: &mut Context<Self>) {
        let bins = self.bins(cx);
        let tree = BinTree::of(&bins);
        let gone = |bin: Option<BinId>| folders.iter().any(|f| tree.within(bin, *f));
        let keep: Vec<Bin> = bins.iter().filter(|b| !gone(Some(b.id))).cloned().collect();
        // Out of a folder that goes, to the nearest one that stays.
        if gone(self.bin) {
            let stay = tree.ancestry(self.bin).find(|b| !gone(Some(*b)));
            self.open_bin(stay, cx);
        }
        self.chosen.retain(|f| !gone(Some(*f)));
        self.also.retain(|a| !media.contains(a));
        if self.selected.is_some_and(|s| media.contains(&s)) {
            self.selected = None;
            self.also.clear();
        }
        self.state
            .update(cx, |s, cx| s.remove_from_pool(&media, Some(keep), cx));
        cx.notify();
    }

    /// Name item `id` in the pool; typing replaces the name, an empty
    /// entry keeps it.
    fn start_item_rename(&mut self, id: MediaId, window: &mut Window, cx: &mut Context<Self>) {
        let Some(item) = self.state.read(cx).bus.project().media(id) else {
            return;
        };
        let name = item_name(item);
        self.renaming_item = Some(id);
        self.item_input.update(cx, |i, cx| {
            i.set_value("", window, cx);
            i.set_placeholder(name, window, cx);
            i.focus(window, cx);
        });
        cx.notify();
    }

    /// The pool's name for the item; its file's name drops the rename.
    fn finish_item_rename(&mut self, name: String, window: &mut Window, cx: &mut Context<Self>) {
        let Some(id) = self.renaming_item.take() else {
            return;
        };
        window.focus(&self.focus, cx);
        let item = self.state.read(cx).bus.project().media(id).cloned();
        if let Some(mut item) = item.filter(|_| !name.is_empty()) {
            let name = (name != file_name(&item.path)).then_some(name);
            if item.name != name {
                item.name = name;
                self.update_media(item, cx);
            }
        }
        cx.notify();
    }

    /// Parts of item `id` the timeline uses, as fractions of it.
    fn used_parts(&self, item: &MediaItem, cx: &App) -> Vec<(f32, f32)> {
        let Some(length) = item
            .info
            .as_ref()
            .map(|i| i.duration.0 as f32)
            .filter(|l| *l > 0.)
        else {
            return Vec::new();
        };
        let tl = &self.state.read(cx).bus.project().timeline;
        tl.tracks
            .iter()
            .flat_map(|t| &t.clips)
            .filter(|c| c.media() == Some(item.id))
            .filter_map(|c| {
                let (a, b) = (c.to_source(c.start)?, c.to_source(c.end())?);
                Some((a.0.min(b.0) as f32 / length, a.0.max(b.0) as f32 / length))
            })
            .collect()
    }

    /// The item's name, or its name field while it is renamed.
    fn name_cell(&self, id: MediaId, look: &Look) -> AnyElement {
        if self.renaming_item == Some(id) {
            return div()
                .min_w_0()
                .flex_1()
                .child(Input::new(&self.item_input).small())
                .into_any_element();
        }
        let color = if look.offline { t::WARN } else { t::T1 };
        div()
            .min_w_0()
            .truncate()
            .text_color(color)
            .child(look.name.clone())
            .into_any_element()
    }

    fn finish_rename(&mut self, name: String, cx: &mut Context<Self>) {
        let Some(id) = self.renaming.take() else {
            return;
        };
        if !name.is_empty() {
            let mut bins = self.bins(cx);
            if let Some(b) = bins.iter_mut().find(|b| b.id == id) {
                b.name = name;
                self.state.update(cx, |s, cx| {
                    s.execute(Command::SetBins { bins }, cx);
                });
            }
        }
        cx.notify();
    }

    /// Files from outside moved over the items, or off them.
    fn drag_files(
        &mut self,
        ev: &DragMoveEvent<ExternalPaths>,
        _: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let over = ev
            .bounds
            .contains(&ev.event.position)
            .then(|| ev.drag(cx).paths().to_vec());
        if over != self.dropping {
            self.dropping = over;
            cx.notify();
        }
    }

    // ------------------------------------------------------------- render

    /// Whether the items shown come from the open folder and every folder
    /// in it, without folders: while searching.
    fn flattened(&self, cx: &App) -> bool {
        !self.search.read(cx).value().trim().is_empty()
    }

    /// The open folder's items, in import order; while searching, the
    /// matches from it and every folder in it.
    fn visible_items(&self, cx: &App) -> Vec<MediaItem> {
        let query = self.search.read(cx).value().trim().to_lowercase();
        let state = self.state.read(cx);
        let project = state.bus.project();
        let tree = BinTree::of(&project.bins);
        let flat = self.flattened(cx);
        project
            .media
            .iter()
            .filter(|m| match (flat, self.bin) {
                (true, None) => true,
                (true, Some(open)) => tree.within(m.bin, open),
                (false, open) => tree.home(m.bin) == open,
            })
            .filter(|m| query.is_empty() || item_name(m).to_lowercase().contains(&query))
            .cloned()
            .collect()
    }

    /// The folders in the open folder, each with how many items it holds,
    /// counting its own folders'; none while searching.
    fn folders(&self, cx: &App) -> Vec<(Bin, usize)> {
        if self.flattened(cx) {
            return Vec::new();
        }
        let project = self.state.read(cx).bus.project();
        let tree = BinTree::of(&project.bins);
        let mut counts: HashMap<BinId, usize> = HashMap::new();
        for item in &project.media {
            for bin in tree.ancestry(item.bin) {
                *counts.entry(bin).or_default() += 1;
            }
        }
        project
            .bins
            .iter()
            .filter(|b| tree.home(b.parent) == self.bin)
            .map(|b| (b.clone(), counts.get(&b.id).copied().unwrap_or(0)))
            .collect()
    }

    /// Open `bin` in the pool; the selection stays behind.
    fn open_bin(&mut self, bin: Option<BinId>, cx: &mut Context<Self>) {
        if self.bin != bin {
            self.bin = bin;
            self.selected = None;
            self.also.clear();
            self.chosen.clear();
            self.cursor = None;
            self.scroll.set_offset(point(px(0.), px(0.)));
        }
        cx.notify();
    }

    /// The Edit panel header's actions while the pool shows: generate and
    /// import.
    pub fn header_actions(&self, cx: &mut Context<Self>) -> AnyElement {
        let generate = Button::new("generate")
            .ghost()
            .small()
            .icon(IconName::Clapperboard)
            .tooltip("Generate");
        h_flex()
            .gap(px(2.))
            .children(self.generate_menu(generate, cx))
            .child(
                Button::new("import")
                    .ghost()
                    .small()
                    .icon(IconName::Plus)
                    .tooltip("Import")
                    .on_click(cx.listener(|this, _, _, cx| this.prompt_import(cx))),
            )
            .into_any_element()
    }

    /// `button` opening what a provider can make; `None` when none can.
    fn generate_menu(&self, button: Button, cx: &mut Context<Self>) -> Option<AnyElement> {
        if !self.can_make(cx) {
            return None;
        }
        let panel = cx.entity();
        let menu = button.dropdown_menu(move |menu, _, cx| generate_items(menu, &panel, cx));
        Some(menu.into_any_element())
    }

    /// Whether a provider can make anything.
    fn can_make(&self, cx: &App) -> bool {
        !self.can_generate(cx).is_empty()
            || self.video_model(cx).is_some()
            || self.can_voiceover(cx)
    }

    fn search_row(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let toggle = |id: &'static str, icon: IconName, tip: &'static str, layout: Layout| {
            Button::new(id)
                .ghost()
                .icon(icon)
                .tooltip(tip)
                .selected(self.layout == layout)
                .on_click(cx.listener(move |this, _, _, cx| {
                    this.layout = layout;
                    cx.notify();
                }))
        };
        h_flex()
            .flex_none()
            .gap(px(4.))
            .p(px(8.))
            .child(
                div()
                    .flex_1()
                    .min_w_0()
                    .child(Input::new(&self.search).search().kbd("/")),
            )
            .child(toggle("grid", IconName::LayoutGrid, "Grid", Layout::Grid))
            .child(toggle("list", IconName::List, "List", Layout::List))
    }

    /// Where the pool is: Media, then each folder down to the open one,
    /// the middle ones folded on a deep path. Each place takes dropped
    /// media.
    fn path_bar(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let project = self.state.read(cx).bus.project();
        let tree = BinTree::of(&project.bins);
        let mut path: Vec<Bin> = tree
            .ancestry(self.bin)
            .filter_map(|id| project.bins.iter().find(|b| b.id == id).cloned())
            .collect();
        path.reverse();
        let mut crumbs: Vec<(Option<BinId>, SharedString)> = vec![(None, "Media".into())];
        let folded = path.len() > 2;
        let shown = if folded {
            &path[path.len() - 2..]
        } else {
            &path[..]
        };
        if folded {
            // "…" goes to the bin above the ones shown.
            crumbs.push((Some(path[path.len() - 3].id), "…".into()));
        }
        crumbs.extend(shown.iter().map(|b| (Some(b.id), b.name.clone().into())));
        let last = crumbs.len() - 1;
        let mut bar = h_flex()
            .flex_none()
            .h(px(28.))
            .px(px(8.))
            .gap(px(2.))
            .text_size(px(12.));
        for (i, (bin, label)) in crumbs.into_iter().enumerate() {
            if i > 0 {
                bar = bar.child(Icon::new(IconName::ChevronRight).size(px(10.)).color(t::T3));
            }
            let current = i == last;
            bar = bar.child(
                div()
                    .id(("crumb", i))
                    .flex_shrink(1.)
                    .min_w(px(16.))
                    .max_w(px(140.))
                    .h(px(22.))
                    .px(px(5.))
                    .flex()
                    .items_center()
                    .rounded(t::RADIUS_SM)
                    .text_color(if current { t::T1 } else { t::T3 })
                    .when(!current, |d| {
                        d.cursor_pointer().hover(|s| s.bg(t::HV).text_color(t::T1))
                    })
                    .drag_over::<MediaDrag>(|s, _, _, _| s.bg(t::AC_WASH))
                    .drag_over::<FolderDrag>(|s, _, _, _| s.bg(t::AC_WASH))
                    .drag_over::<ExternalPaths>(|s, _, _, _| s.bg(t::AC_WASH))
                    .child(div().truncate().child(label))
                    .on_click(cx.listener(move |this, _, _, cx| this.open_bin(bin, cx)))
                    .on_drop(cx.listener(move |this, drag: &MediaDrag, _, cx| {
                        this.move_entries(&drag.all(), &drag.folders, bin, cx)
                    }))
                    .on_drop(cx.listener(move |this, drag: &FolderDrag, _, cx| {
                        this.move_entries(&drag.media, &drag.folders, bin, cx)
                    }))
                    .on_drop(cx.listener(move |this, paths: &ExternalPaths, _, cx| {
                        this.import(paths.paths().to_vec(), bin, cx)
                    })),
            );
        }
        bar
    }

    /// A folder among the items: a click selects it and a double click
    /// opens it, dropped media and folders go in, and its menu renames,
    /// moves or deletes it. A tile in the grid, a row in the list.
    fn folder(&self, bin: &Bin, count: usize, wide: bool, cx: &mut Context<Self>) -> AnyElement {
        let id = bin.id;
        let renaming = self.renaming == Some(id);
        let name = if renaming {
            div()
                .flex_1()
                .min_w_0()
                .child(Input::new(&self.bin_input).small())
                .into_any_element()
        } else {
            div()
                .min_w_0()
                .truncate()
                .child(bin.name.clone())
                .into_any_element()
        };
        let holds = match count {
            0 => "Empty".to_owned(),
            1 => "1 item".to_owned(),
            n => format!("{n} items"),
        };
        let panel = cx.entity();
        let entry = Entry::Folder(id);
        let selected = self.chosen.contains(&id);
        // Grabbing a selected folder drags the selection.
        let drag = {
            let (mut media, folders) = if selected {
                self.split_of(entry)
            } else {
                (Vec::new(), vec![id])
            };
            media = self.in_pool_order(&media, cx);
            FolderDrag {
                folders,
                media,
                name: bin.name.clone().into(),
            }
        };
        let el = div()
            .id(ElementId::Name(format!("folder-{id}").into()))
            .group(SharedString::from(format!("folder-{id}")))
            .min_w_0()
            .cursor_pointer()
            .when(!renaming, |d| {
                d.on_click(cx.listener(move |this, ev: &ClickEvent, window, cx| {
                    cx.stop_propagation();
                    this.click(entry, ev.click_count() >= 2, window, cx)
                }))
                .on_drag(drag, |drag, _, _, cx| cx.new(|_| drag.clone()))
            })
            .on_drop(cx.listener(move |this, drag: &MediaDrag, _, cx| {
                this.move_entries(&drag.all(), &drag.folders, Some(id), cx)
            }))
            .on_drop(cx.listener(move |this, drag: &FolderDrag, _, cx| {
                this.move_entries(&drag.media, &drag.folders, Some(id), cx)
            }))
            .on_drop(cx.listener(move |this, paths: &ExternalPaths, _, cx| {
                this.import(paths.paths().to_vec(), Some(id), cx)
            }));
        let el = el
            .relative()
            .child(self.place_marker(entry))
            .when(self.cursor == Some(entry), |d| {
                d.child(self.reveal_marker())
            });
        let more = folder_more(id, &panel);
        let el = match self.layout {
            Layout::Grid => el
                .flex()
                .flex_col()
                .text_size(px(11.))
                .child(
                    div()
                        .w_full()
                        .aspect_ratio(16. / 9.)
                        .flex()
                        .items_center()
                        .justify_center()
                        .rounded(t::RADIUS_SM)
                        .border_1()
                        .border_color(t::LN)
                        .bg(t::R1)
                        .group_hover(format!("folder-{id}"), |s| s.border_color(t::LN_HV))
                        .when(selected, |d| d.shadow(ring()))
                        .drag_over::<MediaDrag>(|s, _, _, _| s.bg(t::AC_WASH).border_color(t::AC))
                        .drag_over::<FolderDrag>(|s, _, _, _| s.bg(t::AC_WASH).border_color(t::AC))
                        .drag_over::<ExternalPaths>(|s, _, _, _| {
                            s.bg(t::AC_WASH).border_color(t::AC)
                        })
                        .relative()
                        .child(Icon::new(IconName::Folder).size(px(22.)).color(t::T2))
                        .child(more.absolute().top(px(3.)).right(px(3.))),
                )
                .child(div().mt(px(4.)).flex().child(name))
                .child(div().text_size(px(10.)).text_color(t::T3).child(holds)),
            Layout::List => el
                .h(px(30.))
                .flex()
                .items_center()
                .gap(px(10.))
                .px(px(8.))
                .rounded(t::RADIUS)
                .text_size(px(12.))
                .when(selected, |d| {
                    d.bg(t::alpha(t::AC, 0.1))
                        .shadow(inset_ring(t::alpha(t::AC, 0.4)))
                })
                .when(!selected, |d| d.hover(|s| s.bg(t::HV)))
                .drag_over::<MediaDrag>(|s, _, _, _| s.bg(t::AC_WASH))
                .drag_over::<FolderDrag>(|s, _, _, _| s.bg(t::AC_WASH))
                .drag_over::<ExternalPaths>(|s, _, _, _| s.bg(t::AC_WASH))
                .child(
                    div()
                        .flex()
                        .flex_none()
                        .items_center()
                        .justify_center()
                        .w(px(36.))
                        .h(px(20.))
                        .rounded(px(3.))
                        .bg(t::R1)
                        .child(Icon::new(IconName::Folder).size(px(12.)).color(t::T2)),
                )
                .child(h_flex().flex_1().min_w_0().child(name))
                .child(column(holds, 56.).text_color(t::T3))
                .when(wide, |d| d.child(column("", 120.)).child(column("", 90.)))
                .child(more),
        };
        el.context_menu(move |menu, window, cx| bin_menu(menu, &panel, id, window, cx))
            .into_any_element()
    }

    /// What a tile or row shows of `item`.
    fn look(&mut self, item: &MediaItem, cx: &mut Context<Self>) -> Look {
        let thumb = self.thumbs.get(item, &self.state, cx);
        let state = self.state.read(cx);
        let listening = state.source.as_ref().filter(|p| p.is(item));
        let used = state.clips_using(item.id).len();
        Look {
            thumb,
            name: item_name(item).into(),
            meta: meta(item, used),
            listenable: state.can_listen(item),
            // A video's progress shows in the viewer.
            listening: listening
                .filter(|_| item.kind == MediaKind::Audio)
                .map(|p| p.fraction()),
            progress: self.progress(item.id),
            selected: self.selected == Some(item.id) || self.also.contains(&item.id),
            offline: state.offline.contains(&item.id),
        }
    }

    /// The tile's or row's "⋯", shown on hover.
    fn more_button(&self, id: MediaId, group: SharedString, cx: &mut Context<Self>) -> Div {
        let panel = cx.entity();
        div()
            .opacity(0.)
            .group_hover(group, |s| s.opacity(1.))
            .child(
                Button::new(ElementId::Name(format!("media-menu-{id}").into()))
                    .ghost()
                    .xsmall()
                    .icon(IconName::Ellipsis)
                    .dropdown_menu(move |menu, window, cx| item_menu(menu, &panel, id, window, cx)),
            )
    }

    fn tile(&mut self, item: &MediaItem, cx: &mut Context<Self>) -> AnyElement {
        let mut look = self.look(item, cx);
        let id = item.id;
        let group = SharedString::from(format!("media-{id}"));
        // The lead item counts the selection, folders too.
        let picked = self.also.len() + self.chosen.len() + 1;
        let multi = (self.selected == Some(id) && picked > 1).then_some(picked);
        // Skimming: the pointer's place across a video's picture picks
        // the frame.
        let duration = item.info.as_ref().map(|i| i.duration);
        let skimmable = item.kind == MediaKind::Video && !look.offline && duration.is_some();
        let skim = self
            .skim
            .filter(|(m, _)| *m == id && skimmable)
            .map(|(_, f)| f);
        if let Some(f) = skim {
            let slot = (f * thumbs::SKIM_SLOTS as f32) as u32;
            if let Some(image) = self.thumbs.skim(item, slot, &self.state, cx) {
                look.thumb = Some(image);
            }
        }
        let peaks = (item.kind == MediaKind::Audio)
            .then(|| self.thumbs.peaks(item, &self.state, cx))
            .flatten();
        let used = self.used_parts(item, cx);
        let bounds = Rc::new(Cell::new(Bounds::<Pixels>::default()));
        let seen = bounds.clone();
        let mut thumb = thumb_box(&look, item, peaks.as_deref().map(Vec::as_slice))
            .id(ElementId::Name(format!("thumb-{id}").into()))
            .when(look.selected, |d| d.shadow(ring()))
            .child(
                canvas(move |b, _, _| seen.set(b), |_, _, _, _| {})
                    .absolute()
                    .size_full(),
            )
            .when(skimmable, |d| {
                d.on_mouse_move(cx.listener(move |this, ev: &MouseMoveEvent, _, cx| {
                    let b = bounds.get();
                    let f = ((ev.position.x - b.left()) / b.size.width).clamp(0., 1.);
                    this.skim = Some((id, f));
                    cx.notify();
                }))
                .on_hover(cx.listener(move |this, hovered: &bool, _, cx| {
                    if !hovered && this.skim.is_some_and(|(m, _)| m == id) {
                        this.skim = None;
                        cx.notify();
                    }
                }))
            })
            .children(skim.map(|f| {
                div()
                    .absolute()
                    .top_0()
                    .bottom_0()
                    .left(relative(f))
                    .w(px(1.))
                    .bg(t::T1)
            }))
            // What the timeline uses, along the bottom, unless a bar
            // shows progress there.
            .when(look.progress.is_none() && look.listening.is_none(), |d| {
                d.children(used.into_iter().map(|(a, b)| {
                    div()
                        .absolute()
                        .bottom_0()
                        .h(px(2.))
                        .left(relative(a.clamp(0., 1.)))
                        .w(relative((b - a).clamp(0.01, 1.)))
                        .bg(t::OK)
                }))
            })
            // The selection's count takes the corner from the play button.
            .children((look.listenable && multi.is_none()).then(|| {
                div().absolute().top(px(4.)).left(px(4.)).child(listen_dot(
                    format!("listen-{id}"),
                    &self.state,
                    item,
                    px(18.),
                    cx,
                ))
            }))
            .children(multi.map(|n| {
                thumb_badge()
                    .bg(t::AC)
                    .text_color(t::ON_AC)
                    .child(Icon::new(IconName::Check).size(px(9.)))
                    .child(n.to_string())
            }))
            .children(duration.map(|d| {
                // While skimming, where in the item.
                let at = skim.map_or(d, |f| Time((d.0 as f64 * f as f64) as i64));
                duration_chip(at)
            }))
            .child(
                self.more_button(id, group.clone(), cx)
                    .absolute()
                    .top(px(3.))
                    .right(px(3.)),
            );
        if multi.is_none() && !look.listenable {
            thumb = thumb.children(corner_badge(item, look.progress));
        }
        let meta = self.meta_line(&look, id);
        let tile = self
            .item_frame(item, &group, cx)
            .flex()
            .flex_col()
            .min_w_0()
            .text_size(px(11.))
            .child(thumb)
            .child(div().mt(px(4.)).flex().child(self.name_cell(id, &look)))
            .child(meta);
        self.with_menu(tile, id, cx)
    }

    fn row(&mut self, item: &MediaItem, wide: bool, cx: &mut Context<Self>) -> AnyElement {
        let look = self.look(item, cx);
        let id = item.id;
        let group = SharedString::from(format!("media-{id}"));
        let mini = div()
            .relative()
            .flex()
            .flex_none()
            .items_center()
            .justify_center()
            .w(px(36.))
            .h(px(20.))
            .rounded(px(3.))
            .overflow_hidden()
            .bg(thumb_bg(item))
            .map(|d| match (&look.thumb, item.kind) {
                _ if look.offline => {
                    d.child(Icon::new(IconName::Unlink).size(px(11.)).color(t::WARN))
                }
                (Some(image), _) => {
                    d.child(img(image.clone()).size_full().object_fit(ObjectFit::Cover))
                }
                (None, MediaKind::Audio) if look.listenable => d.child(listen_dot(
                    format!("listen-{id}"),
                    &self.state,
                    item,
                    px(16.),
                    cx,
                )),
                (None, MediaKind::Audio) => {
                    d.child(Icon::new(IconName::AudioLines).size(px(11.)).color(t::A))
                }
                (None, MediaKind::Image) => {
                    d.child(Icon::new(IconName::Image).size(px(11.)).color(t::T3))
                }
                (None, MediaKind::Video) => d,
            });
        let bar = look
            .listening
            .map(|f| (f, t::T1))
            .or(look.progress.and_then(Progress::bar));
        let duration = item
            .info
            .as_ref()
            .map_or("—".to_owned(), |i| clock(i.duration));
        let selected = look.selected;
        let more = self.more_button(id, group.clone(), cx);
        let bin = self.bin_name(item.bin, cx);
        let row = self
            .item_frame(item, &group, cx)
            .h(px(30.))
            .flex()
            .items_center()
            .gap(px(10.))
            .px(px(8.))
            .rounded(t::RADIUS)
            .text_size(px(12.))
            .when(selected, |d| {
                d.bg(t::alpha(t::AC, 0.1))
                    .shadow(inset_ring(t::alpha(t::AC, 0.4)))
            })
            .when(!selected, |d| d.hover(|s| s.bg(t::HV)))
            .child(mini)
            .child(
                h_flex()
                    .flex_1()
                    .min_w_0()
                    .gap(px(8.))
                    .child(self.name_cell(id, &look))
                    .children(bar.map(|(f, color)| bar3(f, color).w(px(40.)).flex_none())),
            )
            .child(column(duration, 56.).font_family(t::mono()))
            .when(wide, |d| {
                let format = if look.offline {
                    column("Offline", 120.).text_color(t::WARN)
                } else {
                    column(format_of(item), 120.)
                };
                d.child(format).child(column(bin, 90.))
            })
            .child(more);
        self.with_menu(row, id, cx)
    }

    /// What tiles and rows share: selecting, opening, dragging and the
    /// right-click menu.
    fn item_frame(
        &self,
        item: &MediaItem,
        group: &SharedString,
        cx: &mut Context<Self>,
    ) -> Stateful<Div> {
        let id = item.id;
        // Grabbing a selected item drags the selection, in pool order.
        let drag = match self.dragged.split_first() {
            Some((&first, more)) if self.dragged.contains(&id) => {
                let project = self.state.read(cx).bus.project();
                let name = project.media(first).map(item_name).unwrap_or_default();
                MediaDrag {
                    media: first,
                    name: name.into(),
                    more: more.to_vec(),
                    folders: self.chosen.clone(),
                }
            }
            _ => MediaDrag::one(id, item_name(item).into()),
        };
        div()
            .id(ElementId::Name(group.clone()))
            .group(group.clone())
            .relative()
            .cursor_pointer()
            .on_click(cx.listener(move |this, ev: &ClickEvent, window, cx| {
                cx.stop_propagation();
                this.select(id, ev.click_count() >= 2, window, cx)
            }))
            .on_drag(drag, |drag, _, _, cx| cx.new(|_| drag.clone()))
            .child(self.place_marker(Entry::Media(id)))
            .when(self.cursor == Some(Entry::Media(id)), |d| {
                d.child(self.reveal_marker())
            })
    }

    /// Inside an item or folder: notes where it paints, for the rubber
    /// band.
    fn place_marker(&self, item: Entry) -> impl IntoElement {
        let placed = self.placed.clone();
        canvas(
            move |b, _, _| placed.borrow_mut().push((item, b)),
            |_, _, _, _| {},
        )
        .absolute()
        .size_full()
    }

    /// `p` in the items' own space, which scrolls with them.
    fn in_items(&self, p: Point<Pixels>) -> Point<Pixels> {
        p - self.scroll.offset()
    }

    /// A press on empty space starts a rubber band; with shift or cmd/ctrl
    /// it adds to the selection, else it starts over.
    fn band_start(&mut self, ev: &MouseDownEvent, window: &mut Window, cx: &mut Context<Self>) {
        if self
            .placed
            .borrow()
            .iter()
            .any(|(_, b)| b.contains(&ev.position))
        {
            return;
        }
        window.focus(&self.focus, cx);
        let additive = ev.modifiers.shift || ev.modifiers.secondary();
        if !additive {
            self.deselect(cx);
        }
        let at = self.in_items(ev.position);
        self.band = Some(Band {
            from: at,
            to: at,
            base: self.entries(),
            moved: false,
        });
    }

    /// The band follows the pointer, selecting what it covers.
    fn band_move(&mut self, ev: &MouseMoveEvent, cx: &mut Context<Self>) {
        if self.band.is_none() {
            return;
        }
        if ev.pressed_button != Some(MouseButton::Left) {
            self.band_end(cx);
            return;
        }
        let at = self.in_items(ev.position);
        let offset = self.scroll.offset();
        let Some(band) = self.band.as_mut() else {
            return;
        };
        band.to = at;
        let d = band.to - band.from;
        band.moved |= d.x.abs() > px(3.) || d.y.abs() > px(3.);
        if !band.moved {
            return;
        }
        let rect = band.rect();
        let hits: Vec<Entry> = self
            .placed
            .borrow()
            .iter()
            .filter(|(_, b)| Bounds::new(b.origin - offset, b.size).intersects(&rect))
            .map(|(e, _)| *e)
            .collect();
        let base = band.base.clone();
        let picked: Vec<Entry> = self
            .order(cx)
            .into_iter()
            .filter(|e| base.contains(e) || hits.contains(e))
            .collect();
        self.set_entries(&picked);
        cx.notify();
    }

    fn band_end(&mut self, cx: &mut Context<Self>) {
        if self.band.take().is_some() {
            cx.notify();
        }
    }

    /// The band over the items area, in its coordinates.
    fn band_overlay(&self) -> Option<Div> {
        let band = self.band.as_ref().filter(|b| b.moved)?;
        let rect = band.rect();
        let origin = rect.origin + self.scroll.offset() - self.area.get().origin;
        Some(
            div()
                .absolute()
                .left(origin.x)
                .top(origin.y)
                .w(rect.size.width)
                .h(rect.size.height)
                .border_1()
                .border_color(t::alpha(t::MK, 0.8))
                .bg(t::alpha(t::MK, 0.12)),
        )
    }

    /// Inside the selected item: after an arrow key, scrolls the items so
    /// it shows.
    fn reveal_marker(&self) -> impl IntoElement {
        let (reveal, area, scroll) = (self.reveal.clone(), self.area.clone(), self.scroll.clone());
        canvas(
            move |item, window, _| {
                if !reveal.replace(false) {
                    return;
                }
                let view = area.get();
                let margin = px(8.);
                let mut offset = scroll.offset();
                if item.top() - margin < view.top() {
                    offset.y += view.top() - item.top() + margin;
                } else if item.bottom() + margin > view.bottom() {
                    offset.y -= item.bottom() + margin - view.bottom();
                } else {
                    return;
                }
                scroll.set_offset(offset);
                window.request_animation_frame();
            },
            |_, _, _, _| {},
        )
        .absolute()
        .size_full()
    }

    /// The item's menu on a right click.
    fn with_menu(&self, el: Stateful<Div>, id: MediaId, cx: &mut Context<Self>) -> AnyElement {
        let panel = cx.entity();
        el.context_menu(move |menu, window, cx| item_menu(menu, &panel, id, window, cx))
            .into_any_element()
    }

    /// The tile's second line: the item's format, or what is happening to
    /// it.
    fn meta_line(&self, look: &Look, id: MediaId) -> Stateful<Div> {
        let line = div()
            .id(ElementId::Name(format!("meta-{id}").into()))
            .text_size(px(10.))
            .text_color(t::T3)
            .truncate();
        if look.offline {
            let state = self.state.clone();
            return line.child(
                h_flex().gap(px(3.)).child("Offline ·").child(
                    div()
                        .id(ElementId::Name(format!("relink-{id}").into()))
                        .text_color(t::T2)
                        .hover(|s| s.text_color(t::T1))
                        .child("Relink")
                        .on_click(move |_, _, cx| {
                            cx.stop_propagation();
                            crate::relink::relink_item(&state, id, cx)
                        }),
                ),
            );
        }
        match look.progress {
            Some(Progress::Failed) => line.text_color(t::ERR).child("Analysis failed"),
            Some(Progress::Queued) => line.child("Queued for analysis"),
            Some(Progress::Analyzing(f)) => line.child(format!("Analyzing · {:.0} %", f * 100.)),
            Some(Progress::Proxy(_)) => line.child(format!("{} · proxy building", look.meta)),
            None => line.child(look.meta.clone()),
        }
    }

    fn bin_name(&self, bin: Option<BinId>, cx: &App) -> String {
        bin.and_then(|id| {
            let bins = &self.state.read(cx).bus.project().bins;
            bins.iter().find(|b| b.id == id).map(|b| b.name.clone())
        })
        .unwrap_or_default()
    }

    /// The list's column names, when it is wide enough to have columns.
    fn list_header(&self) -> impl IntoElement {
        h_flex()
            .h(px(24.))
            .gap(px(10.))
            .px(px(8.))
            .text_size(px(10.))
            .text_color(t::T3)
            .child(div().w(px(36.)).flex_none())
            .child(div().flex_1().child("Name"))
            .child(column("Duration", 56.))
            .child(column("Format", 120.))
            .child(column("Folder", 90.))
            .child(div().w(px(20.)).flex_none())
    }

    /// Play and seek for a sound.
    fn listen_bar(&self, item: &MediaItem, cx: &App) -> Option<AnyElement> {
        let state = self.state.read(cx);
        if !state.can_listen(item) {
            return None;
        }
        let source = state.source.as_ref().filter(|p| p.is(item));
        let fraction = source.map_or(0., |p| p.fraction());
        let at = source.map_or(Time::ZERO, |p| p.position());
        let (seeker, sound) = (self.state.clone(), item.clone());
        let bar = seek_bar(
            fraction,
            None,
            move |f, cx| seeker.update(cx, |s, cx| s.seek_source(&sound, f, cx)),
            cx,
        );
        Some(
            h_flex()
                .gap(px(8.))
                .child(listen_dot(
                    "listen-selected",
                    &self.state,
                    item,
                    px(22.),
                    cx,
                ))
                .child(bar)
                .child(
                    div()
                        .font_family(t::mono())
                        .text_size(px(10.))
                        .text_color(t::T3)
                        .child(clock(at)),
                )
                .into_any_element(),
        )
    }

    fn details(&self, item: &MediaItem, cx: &mut Context<Self>) -> AnyElement {
        let mut lines: Vec<SharedString> = Vec::new();
        if let Some(info) = &item.info {
            let mut head = vec![clock(info.duration)];
            if let Some(v) = &info.video {
                head.push(format!("{}×{}", v.width, v.height));
                head.push(format!("{:.2} fps", v.rate.fps()).replace(".00", ""));
                head.push(v.codec.clone());
                head.extend(v.hdr.as_ref().map(|h| h.describe()));
            }
            head.extend(file_type(item));
            lines.push(head.join(" · ").into());
            for a in &info.audio {
                let mut parts = vec![format!("A{}", a.index)];
                parts.extend(a.language.clone());
                parts.push(format!("{} ch", a.channels));
                parts.push(format!("{} kHz", a.sample_rate / 1000));
                parts.push(a.codec.clone());
                lines.push(parts.join(" · ").into());
            }
        }
        let id = item.id;
        v_flex()
            .flex_none()
            .gap(px(6.))
            .px(px(10.))
            .py(px(8.))
            .border_t_1()
            .border_color(t::LN)
            .child(
                h_flex()
                    .gap(px(4.))
                    .child(
                        div()
                            .flex_1()
                            .min_w_0()
                            .font_weight(FontWeight::MEDIUM)
                            .truncate()
                            .child(item_name(item)),
                    )
                    .child(
                        Button::new("remove-media")
                            .ghost()
                            .xsmall()
                            .icon(IconName::Trash)
                            .tooltip("Remove from project")
                            .on_click(cx.listener(move |this, _, window, cx| {
                                this.confirm_remove(vec![id], window, cx)
                            })),
                    ),
            )
            .children(self.listen_bar(item, cx))
            .child(v_flex().gap(px(2.)).children(lines.into_iter().map(|l| {
                div()
                    .text_size(px(11.))
                    .text_color(t::T3)
                    .truncate()
                    .child(l)
            })))
            .into_any_element()
    }

    /// Before the first import: a drop zone with Import and Generate.
    fn empty(&self, cx: &mut Context<Self>) -> AnyElement {
        let generate = Button::new("empty-generate")
            .ghost()
            .icon(IconName::Clapperboard)
            .label("Generate");
        EmptyState::new(IconName::Film, "No media yet")
            .hint("Drop files or folders here")
            .drop_zone()
            .child(
                Button::new("empty-import")
                    .icon(IconName::Download)
                    .label("Import")
                    .on_click(cx.listener(|this, _, _, cx| this.prompt_import(cx))),
            )
            .children(self.generate_menu(generate, cx))
            .into_any_element()
    }

    /// Over the items while files from outside are dragged there.
    fn drop_overlay(&self, paths: &[PathBuf], cx: &App) -> Div {
        let noun = match (paths.len(), paths.iter().any(|p| p.is_dir())) {
            (1, false) => "file",
            (_, false) => "files",
            (1, true) => "folder",
            (_, true) => "items",
        };
        let title = match self.bin {
            Some(_) => format!(
                "Import {} {noun} to {}",
                paths.len(),
                self.bin_name(self.bin, cx)
            ),
            None => format!("Import {} {noun}", paths.len()),
        };
        let mut names: Vec<String> = paths.iter().take(2).map(|p| file_name(p)).collect();
        if paths.len() > 2 {
            names.push(format!("+{}", paths.len() - 2));
        }
        v_flex()
            .absolute()
            .inset(px(6.))
            .items_center()
            .justify_center()
            .gap(px(6.))
            .rounded(px(6.))
            .border_1()
            .border_dashed()
            .border_color(t::AC)
            .bg(t::alpha(t::AC, 0.08))
            .child(
                div()
                    .flex()
                    .items_center()
                    .justify_center()
                    .size(px(30.))
                    .rounded(px(7.))
                    .bg(t::AC_WASH)
                    .child(Icon::new(IconName::Download).size(px(16.)).color(t::AC)),
            )
            .child(div().font_weight(FontWeight::MEDIUM).child(title))
            .child(
                div()
                    .px(px(12.))
                    .max_w_full()
                    .truncate()
                    .font_family(t::mono())
                    .text_size(px(10.))
                    .text_color(t::T2)
                    .child(names.join(" · ")),
            )
    }
}

impl Render for MediaPoolPanel {
    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        if self.dropping.is_some() && !cx.has_active_drag() {
            self.dropping = None;
        }
        let root = v_flex()
            .id("media-pool")
            .size_full()
            .text_size(px(12.))
            .text_color(t::T1)
            .track_focus(&self.focus)
            .key_context("MediaPool")
            .on_action(cx.listener(|this, _: &RemoveSelected, window, cx| {
                let (media, folders) = (this.selection(), this.chosen.clone());
                this.confirm_delete(media, folders, window, cx);
            }))
            .on_action(cx.listener(|this, _: &PlaySelected, _, cx| this.play_selected(cx)))
            .on_action(cx.listener(|this, _: &OpenSelected, _, cx| {
                match this.cursor.filter(|_| this.entries().len() == 1) {
                    Some(Entry::Folder(id)) => this.open_bin(Some(id), cx),
                    _ => {
                        if let Some(id) = this.selected {
                            this.open(id, cx);
                        }
                    }
                }
            }))
            .on_action(cx.listener(|this, _: &SelectAll, _, cx| this.select_all(cx)))
            .on_action(cx.listener(|this, _: &Deselect, _, cx| this.deselect(cx)))
            .on_action(cx.listener(|this, _: &OpenParentBin, _, cx| {
                let bins = &this.state.read(cx).bus.project().bins;
                let parent = BinTree::of(bins).ancestry(this.bin).nth(1);
                this.open_bin(parent, cx)
            }))
            .on_action(
                cx.listener(|this, _: &RenameSelected, window, cx| match this.cursor {
                    Some(Entry::Folder(id)) if this.chosen.contains(&id) => {
                        this.start_rename(id, window, cx)
                    }
                    _ => {
                        if let Some(id) = this.selected {
                            this.start_item_rename(id, window, cx);
                        }
                    }
                }),
            )
            .on_action(cx.listener(|this, _: &MarkSourceIn, _, cx| {
                this.state.update(cx, |s, cx| s.mark_source(false, cx));
            }))
            .on_action(cx.listener(|this, _: &MarkSourceOut, _, cx| {
                this.state.update(cx, |s, cx| s.mark_source(true, cx));
            }))
            .on_action(cx.listener(|this, _: &InsertSelected, _, cx| {
                this.edit_selected(InsertMode::Insert, cx)
            }))
            .on_action(cx.listener(|this, _: &OverwriteSelected, _, cx| {
                this.edit_selected(InsertMode::Overwrite, cx)
            }))
            .on_action(cx.listener(|this, _: &SelectPrev, _, cx| this.step(-1, cx)))
            .on_action(cx.listener(|this, _: &SelectNext, _, cx| this.step(1, cx)))
            .on_action(cx.listener(|this, _: &SelectUp, _, cx| this.step(-this.row_step(), cx)))
            .on_action(cx.listener(|this, _: &SelectDown, _, cx| this.step(this.row_step(), cx)))
            .on_action(cx.listener(|this, _: &FocusSearch, window, cx| {
                this.search.update(cx, |s, cx| s.focus(window, cx));
            }))
            .on_drop(cx.listener(|this, paths: &ExternalPaths, _, cx| {
                this.dropping = None;
                this.import(paths.paths().to_vec(), this.bin, cx)
            }));
        let project = self.state.read(cx).bus.project();
        let generating = self.state.read(cx).generating.clone();
        if project.media.is_empty() && project.bins.is_empty() && generating.is_empty() {
            return root.child(self.empty(cx));
        }

        // The open bin can go, by undo or by another's hand.
        if self
            .bin
            .is_some_and(|id| !project.bins.iter().any(|b| b.id == id))
        {
            self.bin = None;
        }
        self.placed.borrow_mut().clear();
        let items = self.visible_items(cx);
        let folders = self.folders(cx);
        self.dragged = if self.entries().len() < 2 {
            Vec::new()
        } else {
            let selection = self.selection();
            items
                .iter()
                .map(|m| m.id)
                .filter(|id| selection.contains(id))
                .collect()
        };
        let width = self.area.get().size.width.as_f32();
        let wide = width >= WIDE_LIST;
        let content: AnyElement = if items.is_empty() && folders.is_empty() && generating.is_empty()
        {
            let searching = !self.search.read(cx).value().trim().is_empty();
            match searching {
                true => EmptyState::new(IconName::Search, "No matches").compact(),
                false => EmptyState::new(IconName::Inbox, "Nothing in this folder").compact(),
            }
            .into_any_element()
        } else {
            match self.layout {
                Layout::Grid => {
                    let cols = if width > 0. {
                        ((width - 16. + 8.) / (TILE + 8.)).floor().max(1.) as u16
                    } else {
                        2
                    };
                    self.cols.set(cols);
                    let mut tiles: Vec<AnyElement> = folders
                        .iter()
                        .map(|(b, n)| self.folder(b, *n, false, cx))
                        .collect();
                    tiles.extend(generating.iter().map(|g| self.generation_tile(g, cx)));
                    tiles.extend(items.iter().map(|m| self.tile(m, cx)));
                    div()
                        .grid()
                        .grid_cols(cols)
                        .gap_x(px(8.))
                        .gap_y(px(10.))
                        .px(px(8.))
                        .py(px(10.))
                        .children(tiles)
                        .into_any_element()
                }
                Layout::List => {
                    let mut rows: Vec<AnyElement> = folders
                        .iter()
                        .map(|(b, n)| self.folder(b, *n, wide, cx))
                        .collect();
                    rows.extend(generating.iter().map(|g| self.generation_row(g, cx)));
                    rows.extend(items.iter().map(|m| self.row(m, wide, cx)));
                    v_flex()
                        .p(px(4.))
                        .when(wide, |d| d.child(self.list_header()))
                        .children(rows)
                        .into_any_element()
                }
            }
        };
        let measured = self.area.clone();
        let dropping = self.dropping.clone();
        let panel = cx.entity();
        // Details for an item that shows here, not one left in another bin.
        let selected = self
            .selected_item(cx)
            .filter(|item| items.iter().any(|m| m.id == item.id));
        root.child(self.search_row(cx))
            .child(self.path_bar(cx))
            .child(div().flex_none().h(px(1.)).bg(t::LN))
            .child(
                div()
                    .relative()
                    .flex_1()
                    .min_h_0()
                    .on_drag_move(cx.listener(Self::drag_files))
                    .child(
                        canvas(
                            move |b, window, _| {
                                // Columns and the list's layout follow the
                                // width at once, not on the next repaint.
                                if measured.replace(b).size.width != b.size.width {
                                    window.request_animation_frame();
                                }
                            },
                            |_, _, _, _| {},
                        )
                        .absolute()
                        .size_full(),
                    )
                    .child(
                        div()
                            .id("media-items")
                            .size_full()
                            .overflow_y_scroll()
                            .track_scroll(&self.scroll)
                            // A press between items clears the selection;
                            // a drag there draws a rubber band.
                            .on_mouse_down(
                                MouseButton::Left,
                                cx.listener(|this, ev, window, cx| this.band_start(ev, window, cx)),
                            )
                            .on_mouse_move(cx.listener(|this, ev, _, cx| this.band_move(ev, cx)))
                            .on_mouse_up(
                                MouseButton::Left,
                                cx.listener(|this, _, _, cx| this.band_end(cx)),
                            )
                            .on_mouse_up_out(
                                MouseButton::Left,
                                cx.listener(|this, _, _, cx| this.band_end(cx)),
                            )
                            .child(content)
                            .context_menu(move |menu, window, cx| {
                                space_menu(menu, &panel, window, cx)
                            }),
                    )
                    .children(self.band_overlay())
                    .vertical_scrollbar(&self.scroll)
                    .children(dropping.map(|paths| self.drop_overlay(&paths, cx))),
            )
            .children(selected.map(|item| self.details(&item, cx)))
    }
}

/// What a tile or row shows of an item, read once per frame.
struct Look {
    thumb: Option<Arc<Image>>,
    name: SharedString,
    meta: String,
    listenable: bool,
    /// How far the item plays, while it is the source.
    listening: Option<f32>,
    progress: Option<Progress>,
    selected: bool,
    offline: bool,
}

/// The "Analyze" entry of an item's menu: what it says about why it
/// cannot run, or where to go so it can.
#[derive(Clone, Copy)]
enum AnalyzeEntry {
    Queued,
    Running,
    Unreadable,
    /// A model it needs is missing: opens where to get it.
    SetUp,
    /// `again` when it has results, which analyzing replaces.
    Ready {
        again: bool,
    },
}

/// The menu of item `id`, from its "⋯" button or a right click; built as
/// it opens, so what it offers is current.
fn item_menu(
    menu: PopupMenu,
    panel: &Entity<MediaPoolPanel>,
    id: MediaId,
    window: &mut Window,
    cx: &mut Context<PopupMenu>,
) -> PopupMenu {
    let (group, folders) = panel.read(cx).split_of(Entry::Media(id));
    if group.len() + folders.len() > 1 {
        return selection_menu(menu, panel, id, group, folders, window, cx);
    }
    let mut menu = menu;
    let state = panel.read(cx).state.clone();
    if state.read(cx).offline.contains(&id) {
        menu = menu
            .item(
                PopupMenuItem::new("Relink…")
                    .icon(IconName::Unlink)
                    .on_click(move |_, _, cx| crate::relink::relink_item(&state, id, cx)),
            )
            .separator();
    }
    if let Some(entry) = panel.read(cx).analyze_entry(id, cx) {
        let panel = panel.clone();
        menu = menu.item(match entry {
            AnalyzeEntry::Queued => PopupMenuItem::new("Queued for analysis").disabled(true),
            AnalyzeEntry::Running => PopupMenuItem::new("Analyzing…").disabled(true),
            AnalyzeEntry::Unreadable => {
                PopupMenuItem::new("Can’t analyze this file").disabled(true)
            }
            AnalyzeEntry::SetUp => {
                PopupMenuItem::new("Set up analysis…").on_click(|_, window, cx| {
                    window.dispatch_action(Box::new(crate::app::OpenIntegrationsSettings), cx)
                })
            }
            AnalyzeEntry::Ready { again } => {
                let label = if again { "Analyze again" } else { "Analyze" };
                PopupMenuItem::new(label).on_click(move |_, _, cx| {
                    panel.update(cx, |this, cx| this.analyze(id, again, cx))
                })
            }
        });
        menu = menu.separator();
    }
    let (open, remove) = (panel.clone(), panel.clone());
    let state = panel.read(cx).state.clone();
    let sound = state.read(cx).bus.project().media(id);
    let sound = sound
        .filter(|item| state.read(cx).can_listen(item))
        .is_some();
    let open_label = match sound {
        true if listening_to(&state, id, cx) => "Pause",
        true => "Play",
        false => "Open in viewer",
    };
    let rename = panel.clone();
    let mut menu = menu
        .item(
            PopupMenuItem::new(open_label).on_click(move |_, window, cx| {
                open.update(cx, |this, cx| this.select(id, true, window, cx))
            }),
        )
        .item(PopupMenuItem::new("Rename").on_click(move |_, window, cx| {
            rename.update(cx, |this, cx| this.start_item_rename(id, window, cx))
        }));
    let edits = |label: &'static str, mode: InsertMode| {
        let (p, group) = (panel.clone(), group.clone());
        PopupMenuItem::new(label).on_click(move |_, _, cx| {
            let ids = p.read(cx).in_pool_order(&group, cx);
            let state = p.read(cx).state.clone();
            state.update(cx, |s, cx| s.edit_at_playhead(&ids, mode, cx));
        })
    };
    menu = menu
        .separator()
        .item(edits("Insert at playhead", InsertMode::Insert))
        .item(edits("Overwrite at playhead", InsertMode::Overwrite));
    let path = state
        .read(cx)
        .bus
        .project()
        .media(id)
        .map(|m| m.path.clone());
    if let Some(path) = path.filter(|p| p.exists()) {
        menu = menu.item(
            PopupMenuItem::new(crate::ui::deliver::REVEAL)
                .on_click(move |_, _, cx| cx.reveal_path(&path)),
        );
    }
    let menu = move_menu(menu.separator(), panel, &group, &folders, window, cx);
    let menu = if shared::can_save_sound(state.read(cx), id) {
        menu.item(
            PopupMenuItem::new("Add to Library")
                .on_click(move |_, _, cx| state.update(cx, |s, cx| shared::save_sound(s, id, cx))),
        )
    } else {
        menu
    };
    let menu = match voiceover_take(panel, id, cx) {
        Some(take) => {
            let p = panel.clone();
            let state = panel.read(cx).state.clone();
            let saved = voice_saved(&state, &take, cx);
            let menu = menu.item(PopupMenuItem::new("Regenerate…").on_click(
                move |_, window, cx| {
                    let take = Some(take.clone());
                    p.update(cx, |this, cx| this.open_voiceover(take, window, cx))
                },
            ));
            if saved {
                menu
            } else {
                let s = state.clone();
                menu.item(
                    PopupMenuItem::new("Save Voice to Library")
                        .on_click(move |_, _, cx| s.update(cx, |s, cx| save_voice(s, id, cx))),
                )
            }
        }
        None => menu,
    };
    menu.separator().item(
        PopupMenuItem::new("Remove from project")
            .icon(IconName::Trash)
            .destructive()
            .on_click(move |_, window, cx| {
                let (group, folders) = (group.clone(), folders.clone());
                remove.update(cx, |this, cx| {
                    this.confirm_delete(group, folders, window, cx)
                })
            }),
    )
}

/// The menu on several entries: only what applies to every one of them.
/// Clips can go on the timeline and sync; folders only move or go.
fn selection_menu(
    menu: PopupMenu,
    panel: &Entity<MediaPoolPanel>,
    lead: MediaId,
    media: Vec<MediaId>,
    folders: Vec<BinId>,
    window: &mut Window,
    cx: &mut Context<PopupMenu>,
) -> PopupMenu {
    if !folders.is_empty() {
        return common_menu(menu, panel, media, folders, window, cx);
    }
    let mut menu = menu;
    // Analyze when every clip can: each runs fresh or again as it would
    // alone, and "again" only when every one has results.
    let ready: Option<Vec<(MediaId, bool)>> = media
        .iter()
        .map(|m| match panel.read(cx).analyze_entry(*m, cx) {
            Some(AnalyzeEntry::Ready { again }) => Some((*m, again)),
            _ => None,
        })
        .collect();
    if let Some(ready) = ready {
        let label = match ready.iter().all(|(_, again)| *again) {
            true => "Analyze again",
            false => "Analyze",
        };
        let p = panel.clone();
        menu = menu
            .item(PopupMenuItem::new(label).on_click(move |_, _, cx| {
                p.update(cx, |this, cx| {
                    for (id, again) in &ready {
                        this.analyze(*id, *again, cx);
                    }
                })
            }))
            .separator();
    }
    let state = panel.read(cx).state.clone();
    let edits = |label: &'static str, mode: InsertMode| {
        let (p, media) = (panel.clone(), media.clone());
        PopupMenuItem::new(label).on_click(move |_, _, cx| {
            let ids = p.read(cx).in_pool_order(&media, cx);
            let state = p.read(cx).state.clone();
            state.update(cx, |s, cx| s.edit_at_playhead(&ids, mode, cx));
        })
    };
    menu = menu
        .item(edits("Insert at playhead", InsertMode::Insert))
        .item(edits("Overwrite at playhead", InsertMode::Overwrite));
    if let Some((group, recorder)) = panel.read(cx).sync_group(lead, cx) {
        let item = |label: &'static str, mute: bool| {
            let (state, group) = (state.clone(), group.clone());
            PopupMenuItem::new(label).on_click(move |_, _, cx| {
                let group = group.clone();
                state.update(cx, |s, cx| s.sync_media(group, mute, cx))
            })
        };
        menu = menu.separator().item(item("Sync", false));
        if recorder {
            menu = menu.item(item("Sync, Recorder Sound", true));
        }
    }
    common_menu(menu.separator(), panel, media, folders, window, cx)
}

/// What any selection can do: move, and leave the project.
fn common_menu(
    menu: PopupMenu,
    panel: &Entity<MediaPoolPanel>,
    media: Vec<MediaId>,
    folders: Vec<BinId>,
    window: &mut Window,
    cx: &mut Context<PopupMenu>,
) -> PopupMenu {
    let menu = move_menu(menu, panel, &media, &folders, window, cx);
    let label = format!("Remove {} items from project", media.len() + folders.len());
    let remove = panel.clone();
    menu.separator().item(
        PopupMenuItem::new(label)
            .icon(IconName::Trash)
            .destructive()
            .on_click(move |_, window, cx| {
                let (media, folders) = (media.clone(), folders.clone());
                remove.update(cx, |this, cx| {
                    this.confirm_delete(media, folders, window, cx)
                })
            }),
    )
}

/// "Move to", opening the folders `media` and `folders` can go to (not
/// into a folder that moves); ticks the one they all sit in.
fn move_menu(
    menu: PopupMenu,
    panel: &Entity<MediaPoolPanel>,
    media: &[MediaId],
    folders: &[BinId],
    window: &mut Window,
    cx: &mut Context<PopupMenu>,
) -> PopupMenu {
    let project = panel.read(cx).state.read(cx).bus.project();
    let tree = BinTree::of(&project.bins);
    let bins: Vec<(Option<BinId>, String, usize)> = std::iter::once((None, "Media".into(), 0))
        .chain(
            bin_tree(&project.bins)
                .into_iter()
                .filter(|(b, _)| !folders.iter().any(|f| tree.within(Some(b.id), *f)))
                .map(|(b, depth)| (Some(b.id), b.name.clone(), depth + 1)),
        )
        .collect();
    if bins.len() < 2 && folders.is_empty() {
        return menu;
    }
    let mut homes = media
        .iter()
        .filter_map(|m| project.media(*m))
        .map(|m| tree.home(m.bin))
        .chain(
            project
                .bins
                .iter()
                .filter(|b| folders.contains(&b.id))
                .map(|b| tree.home(b.parent)),
        );
    let first = homes.next().flatten();
    let shared = homes.all(|b| b == first).then_some(first);
    let (panel, media, folders) = (panel.clone(), media.to_vec(), folders.to_vec());
    menu.submenu("Move to", window, cx, move |mut menu, _, _| {
        for (bin, name, depth) in &bins {
            let (panel, media, folders, bin) =
                (panel.clone(), media.clone(), folders.clone(), *bin);
            let indent = "    ".repeat(depth.saturating_sub(1));
            menu = menu.item(
                PopupMenuItem::new(format!("{indent}{name}"))
                    .checked(shared == Some(bin))
                    .on_click(move |_, _, cx| {
                        panel.update(cx, |this, cx| this.move_entries(&media, &folders, bin, cx))
                    }),
            );
        }
        menu
    })
}

/// Where an item or folder painted.
type Placed = (Entry, Bounds<Pixels>);

/// A folder or an item: what the pool lists and selects.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Entry {
    Folder(BinId),
    Media(MediaId),
}

/// A rubber band across the items, in their scrolling space.
struct Band {
    from: Point<Pixels>,
    to: Point<Pixels>,
    /// The selection it adds to.
    base: Vec<Entry>,
    /// Past a few pixels: a press that stays put only deselects.
    moved: bool,
}

impl Band {
    fn rect(&self) -> Bounds<Pixels> {
        let (a, b) = (self.from, self.to);
        Bounds::from_corners(
            point(a.x.min(b.x), a.y.min(b.y)),
            point(a.x.max(b.x), a.y.max(b.y)),
        )
    }
}

/// What a provider can make, each opening its form: the Generate
/// button's menu and the Generate submenu.
fn generate_items(mut menu: PopupMenu, panel: &Entity<MediaPoolPanel>, cx: &App) -> PopupMenu {
    let pool = panel.read(cx);
    let (generate, video, can_voiceover) = (
        pool.can_generate(cx),
        pool.video_model(cx),
        pool.can_voiceover(cx),
    );
    for kind in generate {
        let panel = panel.clone();
        menu = menu.item(
            PopupMenuItem::new(format!("{}…", kind.label()))
                .icon(kind.icon())
                .on_click(move |_, window, cx| {
                    panel.update(cx, |this, cx| this.open_generate(kind, window, cx))
                }),
        );
    }
    if let Some(model) = video {
        let p = panel.clone();
        menu = menu.item(PopupMenuItem::new("Video…").icon(IconName::Video).on_click(
            move |_, window, cx| {
                let model = model.clone();
                p.update(cx, |this, cx| this.open_video(model, window, cx))
            },
        ));
    }
    if can_voiceover {
        let p = panel.clone();
        menu = menu.item(
            PopupMenuItem::new("Voiceover…")
                .icon(IconName::Mic)
                .on_click(move |_, window, cx| {
                    p.update(cx, |this, cx| this.open_voiceover(None, window, cx))
                }),
        );
        let p = panel.clone();
        menu =
            menu.separator().item(
                PopupMenuItem::new("Voices…").on_click(move |_, window, cx| {
                    let state = p.read(cx).state.clone();
                    crate::ui::voices::open(
                        state,
                        crate::ui::voices::Start::Find,
                        None,
                        window,
                        cx,
                    );
                }),
            );
    }
    menu
}

/// The menu on a right click between items.
fn space_menu(
    menu: PopupMenu,
    panel: &Entity<MediaPoolPanel>,
    window: &mut Window,
    cx: &mut Context<PopupMenu>,
) -> PopupMenu {
    let (folder, import) = (panel.clone(), panel.clone());
    let can_make = panel.read(cx).can_make(cx);
    let menu = menu
        .item(
            PopupMenuItem::new("New folder")
                .icon(IconName::FolderPlus)
                .on_click(move |_, window, cx| {
                    folder.update(cx, |this, cx| this.new_bin(this.bin, window, cx))
                }),
        )
        .item(
            PopupMenuItem::new("Import…")
                .icon(IconName::Download)
                .on_click(move |_, _, cx| import.update(cx, |this, cx| this.prompt_import(cx))),
        );
    if !can_make {
        return menu;
    }
    let panel = panel.clone();
    menu.submenu("Generate", window, cx, move |menu, _, cx| {
        generate_items(menu, &panel, cx)
    })
}

/// The bins by parent, for walking up from a bin.
struct BinTree(HashMap<BinId, Option<BinId>>);

impl BinTree {
    fn of(bins: &[Bin]) -> Self {
        Self(bins.iter().map(|b| (b.id, b.parent)).collect())
    }

    /// Where something in `bin` shows: that bin, or the top level when
    /// the bin is gone.
    fn home(&self, bin: Option<BinId>) -> Option<BinId> {
        bin.filter(|b| self.0.contains_key(b))
    }

    /// `bin`, then each bin it sits in, up to the top level.
    fn ancestry(&self, bin: Option<BinId>) -> impl Iterator<Item = BinId> + '_ {
        let mut at = self.home(bin);
        // A bad parent loop stops after this many.
        let mut left = self.0.len();
        std::iter::from_fn(move || {
            let here = at.filter(|_| left > 0)?;
            left -= 1;
            at = self.home(self.0.get(&here).copied().flatten());
            Some(here)
        })
    }

    /// Whether something in `bin` is in `open` or a bin inside it.
    fn within(&self, bin: Option<BinId>, open: BinId) -> bool {
        self.ancestry(bin).any(|b| b == open)
    }
}

/// A folder's "⋯", shown on hover, opening its menu. A press on it
/// stays with it: the folder underneath would open.
fn folder_more(id: BinId, panel: &Entity<MediaPoolPanel>) -> Div {
    let panel = panel.clone();
    div()
        .flex_none()
        .opacity(0.)
        .group_hover(format!("folder-{id}"), |s| s.opacity(1.))
        .on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())
        .child(
            Button::new(ElementId::Name(format!("folder-menu-{id}").into()))
                .ghost()
                .xsmall()
                .icon(IconName::Ellipsis)
                .dropdown_menu(move |menu, window, cx| bin_menu(menu, &panel, id, window, cx)),
        )
}

/// A folder's menu, from its "⋯" or a right click: for the selection when
/// the folder is in it.
fn bin_menu(
    menu: PopupMenu,
    panel: &Entity<MediaPoolPanel>,
    id: BinId,
    window: &mut Window,
    cx: &mut Context<PopupMenu>,
) -> PopupMenu {
    let (media, folders) = panel.read(cx).split_of(Entry::Folder(id));
    if media.len() + folders.len() > 1 {
        let lead = media.first().copied();
        return match lead {
            Some(lead) => selection_menu(menu, panel, lead, media, folders, window, cx),
            None => common_menu(menu, panel, media, folders, window, cx),
        };
    }
    let rename = panel.clone();
    let menu = menu.item(PopupMenuItem::new("Rename").on_click(move |_, window, cx| {
        rename.update(cx, |this, cx| this.start_rename(id, window, cx))
    }));
    let menu = move_menu(menu, panel, &media, &folders, window, cx);
    let delete = panel.clone();
    menu.separator().item(
        PopupMenuItem::new("Delete folder")
            .icon(IconName::Trash)
            .destructive()
            .on_click(move |_, window, cx| {
                let (media, folders) = (media.clone(), folders.clone());
                delete.update(cx, |this, cx| {
                    this.confirm_delete(media, folders, window, cx)
                })
            }),
    )
}

/// The voiceover `id` is, when a provider can make it again.
fn voiceover_take(
    panel: &Entity<MediaPoolPanel>,
    id: MediaId,
    cx: &App,
) -> Option<voiceover::Take> {
    let panel = panel.read(cx);
    let state = panel.state.read(cx);
    let generated = state.bus.project().media(id)?.generated.as_deref()?;
    let reading = generated.reading.clone()?;
    panel.can_voiceover(cx).then(|| voiceover::Take {
        script: generated.prompt.clone(),
        reading,
    })
}

/// Whether the voice that read `take` is in the library.
fn voice_saved(state: &Entity<EditorState>, take: &voiceover::Take, cx: &App) -> bool {
    let state = state.read(cx);
    let provider = state.voice_provider().unwrap_or_default();
    state
        .library
        .voice_of(&provider, &take.reading.voice)
        .is_some()
}

/// Keep the voice that read voiceover `id` in the library, with the
/// voiceover as its sample.
fn save_voice(s: &mut EditorState, id: MediaId, cx: &mut Context<EditorState>) {
    let Some(item) = s.bus.project().media(id).cloned() else {
        return;
    };
    let Some(reading) = item.generated.as_deref().and_then(|g| g.reading.clone()) else {
        return;
    };
    let known = s
        .account_voices
        .voices
        .iter()
        .flatten()
        .find(|v| v.id == reading.voice)
        .cloned();
    let voice = known.unwrap_or_else(|| flikk_core::cloud::Voice {
        id: reading.voice.clone(),
        name: reading.voice_name.clone(),
        ..Default::default()
    });
    s.keep_voice(
        &voice,
        flikk_core::cloud::VoiceOrigin::Account,
        Some(&item),
        cx,
    );
    s.keep_reading(&reading, cx);
}

/// Whether pool item `id` is playing.
fn listening_to(state: &Entity<EditorState>, id: MediaId, cx: &App) -> bool {
    let state = state.read(cx);
    let item = state.bus.project().media(id);
    let preview = state.source.as_ref();
    item.zip(preview)
        .is_some_and(|(item, p)| p.is(item) && p.is_playing())
}

/// `bins` in tree order, each with how deep it sits.
fn bin_tree(bins: &[Bin]) -> Vec<(&Bin, usize)> {
    fn under<'a>(
        bins: &'a [Bin],
        parent: Option<BinId>,
        depth: usize,
        out: &mut Vec<(&'a Bin, usize)>,
    ) {
        for bin in bins.iter().filter(|b| b.parent == parent) {
            out.push((bin, depth));
            under(bins, Some(bin.id), depth + 1, out);
        }
    }
    let mut out = Vec::new();
    under(bins, None, 0, &mut out);
    // A bin whose parent is gone sits at the top.
    for bin in bins {
        if !out.iter().any(|(b, _)| b.id == bin.id) {
            out.push((bin, 0));
            under(bins, Some(bin.id), 1, &mut out);
        }
    }
    out
}

/// A fixed-width list column.
fn column(text: impl Into<SharedString>, width: f32) -> Div {
    div()
        .w(px(width))
        .flex_none()
        .truncate()
        .text_size(px(11.))
        .text_color(t::T2)
        .child(text.into())
}

/// The 16:9 picture of a tile: the frame, or the kind's mark, the offline
/// veil and the progress along the bottom.
fn thumb_box(look: &Look, item: &MediaItem, peaks: Option<&[f32]>) -> Div {
    let bar = look
        .listening
        .map(|f| (f, t::T1))
        .or(look.progress.and_then(Progress::bar));
    div()
        .relative()
        .w_full()
        .aspect_ratio(16. / 9.)
        .rounded(t::RADIUS_SM)
        .overflow_hidden()
        .bg(thumb_bg(item))
        .map(|d| match (&look.thumb, item.kind) {
            (Some(image), _) => {
                d.child(img(image.clone()).size_full().object_fit(ObjectFit::Cover))
            }
            (None, MediaKind::Audio) => match peaks {
                Some(peaks) => d.child(waveform(peaks)),
                None => d.child(
                    div()
                        .absolute()
                        .inset_0()
                        .flex()
                        .items_center()
                        .justify_center()
                        .child(Icon::new(IconName::AudioLines).size(px(22.)).color(t::A)),
                ),
            },
            (None, MediaKind::Image) => d.child(
                div()
                    .absolute()
                    .inset_0()
                    .flex()
                    .items_center()
                    .justify_center()
                    .child(Icon::new(IconName::Image).size(px(16.)).color(t::T3)),
            ),
            (None, MediaKind::Video) => d,
        })
        .when(look.offline, |d| {
            d.child(
                div()
                    .absolute()
                    .inset_0()
                    .flex()
                    .items_center()
                    .justify_center()
                    .bg(t::alpha(t::G, 0.7))
                    .child(Icon::new(IconName::Unlink).size(px(14.)).color(t::WARN)),
            )
        })
        .children(bar.map(|(f, color)| {
            div()
                .absolute()
                .left_0()
                .bottom_0()
                .h(px(2.))
                .w(relative(f.clamp(0., 1.)))
                .bg(color)
        }))
}

/// A sound's peaks across a tile, mirrored about the middle.
fn waveform(peaks: &[f32]) -> Div {
    h_flex()
        .absolute()
        .left(px(6.))
        .right(px(6.))
        .top(px(16.))
        .bottom(px(16.))
        .items_center()
        .gap(px(1.))
        .children(peaks.iter().map(|p| {
            div()
                .flex_1()
                .min_w(px(1.))
                .h(relative(p.clamp(0.04, 1.)))
                .rounded(px(1.))
                .bg(t::alpha(t::A, 0.8))
        }))
}

/// The ground of a thumbnail before (or without) its frame.
fn thumb_bg(item: &MediaItem) -> Rgba {
    match item.kind {
        // Opaque: the selection ring is a shadow, which shows through.
        MediaKind::Audio => over(t::A, 0.1, t::P),
        _ => t::R1,
    }
}

/// `c` at `alpha` laid over `ground`, as one opaque colour.
fn over(c: Rgba, alpha: f32, ground: Rgba) -> Rgba {
    let mix = |a: f32, b: f32| b + (a - b) * alpha;
    Rgba {
        r: mix(c.r, ground.r),
        g: mix(c.g, ground.g),
        b: mix(c.b, ground.b),
        a: 1.,
    }
}

/// A small label in a thumbnail's top-left corner.
fn thumb_badge() -> Div {
    h_flex()
        .absolute()
        .top(px(3.))
        .left(px(3.))
        .gap(px(3.))
        .h(px(14.))
        .px(px(4.))
        .rounded(px(3.))
        .bg(t::alpha(t::G, 0.67))
        .text_size(px(9.))
        .line_height(px(14.))
        .text_color(t::T1)
}

/// The badge a tile wears in its corner: what is happening to it, else
/// who read it or HDR.
fn corner_badge(item: &MediaItem, progress: Option<Progress>) -> Option<Div> {
    match progress {
        Some(Progress::Failed) => {
            return Some(
                thumb_badge()
                    .text_color(t::ERR)
                    .child(Icon::new(IconName::CircleAlert).size(px(9.)))
                    .child("Failed"),
            );
        }
        Some(Progress::Analyzing(_)) => {
            return Some(
                thumb_badge()
                    .child(Spinner::new().size(px(8.)))
                    .child("Analyzing"),
            );
        }
        Some(Progress::Proxy(f)) => {
            return Some(
                thumb_badge()
                    .font_family(t::mono())
                    .text_color(t::T2)
                    .child(format!("Proxy {:.0} %", f * 100.)),
            );
        }
        Some(Progress::Queued) | None => {}
    }
    let reading = item.generated.as_deref().and_then(|g| g.reading.as_ref());
    if let Some(reading) = reading {
        return Some(
            thumb_badge()
                .child(Icon::new(IconName::Mic).size(px(9.)))
                .child(reading.voice_name.clone()),
        );
    }
    flikk_core::hdr::hdr_of(item)?;
    Some(thumb_badge().font_weight(FontWeight::SEMIBOLD).child("HDR"))
}

/// The duration over a thumbnail's bottom-right corner.
fn duration_chip(duration: Time) -> impl IntoElement {
    div()
        .absolute()
        .right(px(3.))
        .bottom(px(3.))
        .px(px(3.))
        .rounded(px(2.))
        .bg(t::alpha(t::G, 0.67))
        .font_family(t::mono())
        .font_weight(FontWeight::MEDIUM)
        .text_size(px(9.))
        .text_color(t::T1)
        .child(clock(duration))
}

/// A 3 px bar at `fraction` in `color`.
fn bar3(fraction: f32, color: Rgba) -> Div {
    div()
        .h(px(3.))
        .rounded_full()
        .bg(t::alpha(t::T1, 0.08))
        .child(
            div()
                .h_full()
                .rounded_full()
                .w(relative(fraction.clamp(0., 1.)))
                .bg(color),
        )
}

/// Selection: a 1.5 px accent ring around a thumbnail.
fn ring() -> Vec<BoxShadow> {
    vec![BoxShadow {
        color: t::AC.into(),
        offset: point(px(0.), px(0.)),
        blur_radius: px(0.),
        spread_radius: px(1.5),
        inset: false,
    }]
}

/// A 1 px ring inside a selected row.
fn inset_ring(color: Rgba) -> Vec<BoxShadow> {
    vec![BoxShadow {
        color: color.into(),
        offset: point(px(0.), px(0.)),
        blur_radius: px(0.),
        spread_radius: px(1.),
        inset: true,
    }]
}

/// "4K · 25p · used ×3", "WAV · 48 kHz", "Voiceover · 112 words".
fn meta(item: &MediaItem, used: usize) -> String {
    let mut parts: Vec<String> = Vec::new();
    let ext = item
        .path
        .extension()
        .map(|e| e.to_string_lossy().to_uppercase());
    let script = item
        .generated
        .as_deref()
        .filter(|g| g.reading.is_some())
        .map(|g| g.prompt.split_whitespace().count());
    if let Some(words) = script {
        parts.push("Voiceover".into());
        parts.push(format!("{words} words"));
    } else if let Some(v) = item.info.as_ref().and_then(|i| i.video.as_ref()) {
        if item.kind == MediaKind::Image {
            parts.extend(ext);
            parts.push(format!("{}×{}", v.width, v.height));
        } else {
            parts.push(resolution(v.width, v.height));
            parts.push(format!("{}p", trim_rate(v.rate.fps())));
        }
    } else {
        parts.extend(ext);
        if let Some(a) = item.info.as_ref().and_then(|i| i.audio.first()) {
            parts.push(format!("{} kHz", a.sample_rate / 1000));
        }
    }
    if used > 0 {
        parts.push(format!("used ×{used}"));
    }
    parts.join(" · ")
}

/// The list's format column: picture size and rate, or the first sound.
fn format_of(item: &MediaItem) -> String {
    let Some(info) = &item.info else {
        return String::new();
    };
    if let Some(v) = &info.video {
        if item.kind == MediaKind::Image {
            return format!("{}×{}", v.width, v.height);
        }
        return format!("{}×{} · {} fps", v.width, v.height, trim_rate(v.rate.fps()));
    }
    info.audio
        .first()
        .map(|a| {
            format!(
                "A{} · {} ch · {} kHz",
                a.index,
                a.channels,
                a.sample_rate / 1000
            )
        })
        .unwrap_or_default()
}

/// "4K", "6K", or the height for HD and smaller.
fn resolution(width: u32, height: u32) -> String {
    match width {
        w if w >= 7680 => "8K".into(),
        w if w >= 6144 => "6K".into(),
        w if w >= 5120 => "5K".into(),
        w if w >= 3840 => "4K".into(),
        _ => height.to_string(),
    }
}

/// "25", "29.97".
fn trim_rate(fps: f64) -> String {
    let s = format!("{fps:.2}");
    s.trim_end_matches('0').trim_end_matches('.').to_owned()
}

/// "MP4", "WAV": the file's extension, else the first name the
/// container goes by ("mov,mp4,m4a,…" is one demuxer).
fn file_type(item: &MediaItem) -> Option<String> {
    let ext = item
        .path
        .extension()
        .map(|e| e.to_string_lossy().to_uppercase());
    let container = item.info.as_ref().and_then(|i| {
        let first = i.container.split(',').next()?.trim();
        (!first.is_empty()).then(|| first.to_uppercase())
    });
    ext.or(container)
}

fn file_name(path: &std::path::Path) -> String {
    path.file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_else(|| path.display().to_string())
}

/// A bar at `fraction`; a click on it calls `seek` with where, 0..1.
pub(crate) fn seek_bar(
    fraction: f32,
    marked: Option<(f32, f32)>,
    seek: impl Fn(f32, &mut App) + 'static,
    _: &App,
) -> impl IntoElement {
    let bounds = Rc::new(Cell::new(Bounds::<Pixels>::default()));
    let seen = bounds.clone();
    div()
        .relative()
        .flex_1()
        .min_w_0()
        .h(px(14.))
        .flex()
        .items_center()
        .cursor_pointer()
        .on_mouse_down(MouseButton::Left, move |ev, _, cx| {
            let b = bounds.get();
            seek((ev.position.x - b.left()) / b.size.width, cx);
        })
        .child(
            canvas(move |b, _, _| seen.set(b), |_, _, _, _| {})
                .absolute()
                .size_full(),
        )
        .children(marked.map(|(a, b)| {
            // The marked part, under the position.
            let (a, b) = (a.clamp(0., 1.), b.clamp(0., 1.));
            div()
                .absolute()
                .left(relative(a))
                .w(relative((b - a).max(0.)))
                .h(px(9.))
                .rounded(px(2.))
                .bg(t::alpha(t::AC, 0.3))
        }))
        .child(bar3(fraction, t::T1).w_full())
}

/// Play or pause `item` from a row or form: an icon button that holds the
/// hover surface while it plays.
pub(crate) fn listen_button(
    id: impl Into<ElementId>,
    state: &Entity<EditorState>,
    item: &MediaItem,
    cx: &App,
) -> Button {
    let preview = state.read(cx).source.as_ref();
    let playing = preview.is_some_and(|p| p.is(item) && p.is_playing());
    let (state, item) = (state.clone(), item.clone());
    play_button(id, playing)
        .tooltip(if playing { "Pause" } else { "Play" })
        .on_click(move |_, _, cx| {
            cx.stop_propagation();
            state.update(cx, |s, cx| s.toggle_source(&item, cx));
        })
}

/// The row play button's look, without what it plays.
pub(crate) fn play_button(id: impl Into<ElementId>, playing: bool) -> Button {
    Button::new(id)
        .ghost()
        .small()
        .icon(if playing {
            IconName::Pause
        } else {
            IconName::Play
        })
        .selected(playing)
}

/// A round play button `size` across; white while `item` plays.
pub(crate) fn listen_dot(
    id: impl Into<ElementId>,
    state: &Entity<EditorState>,
    item: &MediaItem,
    size: Pixels,
    cx: &App,
) -> Stateful<Div> {
    let preview = state.read(cx).source.as_ref();
    let playing = preview.is_some_and(|p| p.is(item) && p.is_playing());
    let (state, item) = (state.clone(), item.clone());
    play_dot(id, playing, size)
        .tooltip(Tooltip::text(if playing { "Pause" } else { "Play" }))
        .on_click(move |_, _, cx| {
            cx.stop_propagation();
            state.update(cx, |s, cx| s.toggle_source(&item, cx));
        })
}

/// The round play button's look, without what it plays.
pub(crate) fn play_dot(id: impl Into<ElementId>, playing: bool, size: Pixels) -> Stateful<Div> {
    div()
        .id(id)
        .flex()
        .flex_none()
        .items_center()
        .justify_center()
        .size(size)
        .rounded_full()
        .cursor_pointer()
        .when(playing, |d| d.bg(t::T1).text_color(t::G))
        .when(!playing, |d| {
            d.bg(t::HV).text_color(t::T1).hover(|s| s.bg(t::PS))
        })
        .on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())
        .child(
            Icon::new(if playing {
                IconName::Pause
            } else {
                IconName::Play
            })
            .size(size * 0.45),
        )
}

#[derive(Clone, Copy)]
enum Progress {
    Proxy(f32),
    Queued,
    Analyzing(f32),
    Failed,
}

impl Progress {
    /// The bar along the thumbnail's bottom: how far, in what colour.
    fn bar(self) -> Option<(f32, Rgba)> {
        match self {
            Progress::Proxy(f) => Some((f, t::T2)),
            Progress::Analyzing(f) => Some((f, t::AC)),
            Progress::Queued | Progress::Failed => None,
        }
    }
}

pub(crate) fn item_name(item: &MediaItem) -> String {
    if let Some(name) = &item.name {
        return name.clone();
    }
    item.path
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_else(|| item.path.display().to_string())
}

/// `M:SS`, or `H:MM:SS` past an hour.
pub(crate) fn clock(t: Time) -> String {
    let s = t.as_secs_f64().max(0.0).round() as i64;
    if s >= 3600 {
        format!("{}:{:02}:{:02}", s / 3600, s / 60 % 60, s % 60)
    } else {
        format!("{}:{:02}", s / 60, s % 60)
    }
}
